// ---- core.js
// C(topic, difficulty 1-4, question, answer, hint?)
// Answer format: first line = the direct answer. Then lines starting with "- " = short reasoning bullets.
window.CARDS = window.CARDS || [];
window.C = function(topic, diff, q, a, hint){ window.CARDS.push({topic:topic, diff:diff, q:q, a:a, hint:hint||''}); };


// ---- accounting.js
;(function(){
var T="Accounting";
C(T,1,"Walk me through the three financial statements.","Income statement shows profit over a period, balance sheet shows what the company owns and owes at a point in time, cash flow statement turns net income into cash.\n- IS: revenue down to net income.\n- BS: assets = liabilities + equity.\n- CFS: net income, add back non-cash items and working capital, then investing and financing.");
C(T,1,"How do the three statements link together?","Net income is the bridge.\n- Net income tops the CFS and flows into retained earnings.\n- Ending cash on the CFS becomes cash on the BS.\n- D&A, capex, debt and equity flows on the CFS roll the other BS lines forward.");
C(T,2,"If you could only use one statement to judge a business, which would you pick?","The cash flow statement.\n- It shows whether the business actually generates cash.\n- Cash is the hardest number to dress up with accounting choices.");
C(T,2,"If you could use two statements, which two and why?","Starting balance sheet plus income statement.\n- With those you can rebuild the cash flow statement and the ending balance sheet.");
C(T,1,"Depreciation rises by $10. Tax rate 25%. Walk it through.","Net income -7.5, cash +2.5.\n- IS: EBIT -10, tax -2.5, NI -7.5.\n- CFS: NI -7.5, add back 10, cash +2.5.\n- BS: cash +2.5, PP&E -10, so assets -7.5; retained earnings -7.5.");
C(T,1,"A company buys $100 of equipment with cash. Walk it through.","No income statement impact yet.\n- CFS: capex -100 in investing.\n- BS: cash -100, PP&E +100. Total assets unchanged.");
C(T,2,"That $100 of equipment has a 5-year life. Tax rate 50%. What happens at the end of year 1?","Net income -10, cash +10.\n- Depreciation 20, tax saving 10, NI -10.\n- CFS: NI -10 + depreciation 20 = +10.\n- BS: cash +10, PP&E -20; retained earnings -10.");
C(T,2,"An asset is written down by $95. Tax rate 40%, assume it is deductible. Walk it through.","Net income -57, cash +38.\n- Pretax -95, tax saving 38.\n- CFS: add back the non-cash 95, so cash +38.\n- BS: asset -95, cash +38 (assets -57); retained earnings -57.\n- If not deductible yet, book a DTA of 38 instead of cash.");
C(T,2,"Goodwill is impaired by $50. Walk it through.","Net income -50, cash unchanged.\n- Goodwill impairment is usually not tax deductible, so no tax saving.\n- CFS: NI -50, add back 50.\n- BS: goodwill -50, retained earnings -50.");
C(T,2,"A company sells $50 of product that cost $20 in inventory. Tax rate 50%, paid in cash. Walk it through.","Net income +15, cash +35.\n- Revenue 50, COGS 20, tax 15, NI 15.\n- CFS: NI 15 + inventory decrease 20 = 35.\n- BS: cash +35, inventory -20; retained earnings +15.");
C(T,1,"A company buys $100 of inventory with cash. Walk it through.","No income statement impact.\n- CFS: inventory increase -100 in operating.\n- BS: cash -100, inventory +100.");
C(T,1,"A company buys $100 of inventory using debt. Walk it through.","No income statement impact, cash unchanged.\n- CFS: inventory -100 in operating, debt +100 in financing.\n- BS: inventory +100, debt +100.");
C(T,2,"A customer pays $120 upfront for a 12-month subscription. What does it look like after 3 months?","Revenue 30, deferred revenue 90, cash 120.\n- At signing: cash +120, deferred revenue +120.\n- Each month 10 moves from deferred revenue to revenue.\n- CFS: NI includes the 30; the +90 deferred revenue is a working capital inflow.");
C(T,1,"A company sells a $100 gift card. Walk it through.","Cash +100, deferred revenue +100, no revenue yet.\n- Revenue is recognized only when the card is redeemed.\n- CFS: +100 from the deferred revenue increase in operating.");
C(T,1,"A company pays $10 of cash interest. Tax rate 25%. Walk it through.","Net income -7.5, cash -7.5.\n- IS: interest 10, tax saving 2.5.\n- CFS: only the NI change, nothing to add back.\n- BS: cash -7.5, retained earnings -7.5.");
C(T,3,"PIK interest of $10 accrues. Tax rate 25%. Walk it through.","Net income -7.5, cash +2.5, debt +10.\n- Interest expense hits the IS and is deductible.\n- It is non-cash, so add back 10 on the CFS.\n- Cash rises by the 2.5 tax shield; the 10 is added to the debt balance.");
C(T,3,"A company buys a $100 factory with debt at 10%. Over the year: $10 depreciation, $20 debt repaid, tax 25%. Walk it through.","Net income -15, cash -25.\n- IS: depreciation 10 + interest 10 = -20 pretax, tax +5, NI -15.\n- CFS: operations -5, investing -100, financing +100 - 20 = +80.\n- BS: cash -25, PP&E 90 (assets +65); debt 80, retained earnings -15.");
C(T,1,"Why does an increase in accounts payable increase cash flow?","Because the expense has been recorded but the cash has not left yet.\n- The expense already lowered net income.\n- Adding back the AP increase shows you effectively borrowed from suppliers.");
C(T,1,"Why does an increase in net working capital reduce cash flow?","More cash gets tied up in operations.\n- Receivables and inventory growing faster than payables means cash is stuck in the business.\n- So operating cash flow is below what net income suggests.");
C(T,2,"Can working capital be negative? When does that happen?","Yes, when current liabilities exceed current assets.\n- Common when customers pay before delivery: subscriptions, airlines, restaurants, grocery.\n- Customers are effectively funding the business, which is usually a good sign.");
C(T,2,"Two companies have the same net income but different depreciation. Which has more cash from operations?","The one with more depreciation.\n- Depreciation is non-cash and gets added back.\n- Same net income plus a bigger add-back means more CFO.");
C(T,2,"How can a profitable company run out of cash?","Profit is accrual based; cash is not.\n- Working capital build from fast growth (receivables, inventory).\n- Heavy capex or debt repayments.\n- Revenue booked before cash is collected.");
C(T,2,"A company sells PP&E carried at $110 for $150. Tax rate 30%. Walk it through.","Net income +28, cash +138.\n- Gain 40, tax 12, NI +28.\n- CFS: NI 28, subtract the 40 gain in operating, add 150 proceeds in investing.\n- BS: cash +138, PP&E -110 (assets +28); retained earnings +28.");
C(T,2,"Why do companies use accelerated depreciation for tax but straight-line for reporting?","To pay less tax now while showing smoother earnings.\n- Bigger early deductions defer cash taxes.\n- The gap between book and tax creates a deferred tax liability.");
C(T,2,"What is a deferred tax asset versus a deferred tax liability?","Future tax savings versus future tax owed.\n- DTL: book taxes exceed cash taxes today, e.g. accelerated tax depreciation.\n- DTA: you will pay less tax later, e.g. NOLs or expenses booked before they are deductible.");
C(T,3,"Why are deferred tax liabilities created in an M&A deal?","Asset write-ups in a stock deal are book only.\n- Book D&A rises but tax D&A does not.\n- That future gap is recorded today as a DTL equal to write-up x tax rate.");
C(T,3,"How do you calculate goodwill in an acquisition?","Purchase equity value minus the fair value of net identifiable assets.\n- Start with target book equity, remove existing goodwill.\n- Add asset write-ups, subtract the new DTL on those write-ups.\n- What is left over is goodwill; it is tested for impairment, not amortized.");
C(T,1,"What is the difference between capex and opex?","Capex is capitalized and depreciated; opex is expensed right away.\n- Capex buys a long-lived asset.\n- Moving a cost from opex to capex raises EBITDA but not cash flow.");
C(T,2,"Prices are rising. What happens if a company switches from FIFO to LIFO?","Lower net income, lower taxes, higher cash flow.\n- LIFO matches the newest, more expensive inventory to sales, so COGS is higher.\n- Lower taxable income means less cash tax paid.\n- Ending inventory on the BS is valued at older, cheaper costs.");
C(T,1,"What is the difference between accounts receivable and deferred revenue?","Revenue earned but not yet paid versus cash received but not yet earned.\n- AR is an asset.\n- Deferred revenue is a liability.");
C(T,2,"A company records $10 of stock-based compensation. Tax rate 25%, assume deductible. Walk it through.","Net income -7.5, cash +2.5, equity +2.5.\n- Expense 10, tax saving 2.5.\n- CFS: add back the non-cash 10, cash +2.5.\n- BS: retained earnings -7.5, APIC +10, so equity +2.5, matching cash.");
C(T,2,"Is stock-based compensation a real expense even though it is added back on the cash flow statement?","Yes.\n- It is non-cash, but it pays employees with ownership.\n- Shareholders bear the cost through dilution.\n- Adding it back and ignoring the dilution overstates value.");
C(T,1,"A company buys back $100 of shares. Walk it through.","Cash -100, equity -100, no income statement impact.\n- CFS: -100 in financing.\n- BS: treasury stock reduces equity by 100.");
C(T,1,"A company pays a $100 dividend. Walk it through.","Cash -100, retained earnings -100, no income statement impact.\n- CFS: -100 in financing.");
C(T,1,"A company issues $100 of new shares. Walk it through.","Cash +100, equity +100.\n- CFS: +100 in financing.\n- No income statement impact.");
C(T,1,"A company repays $100 of debt principal. Walk it through.","Cash -100, debt -100.\n- CFS: -100 in financing.\n- Principal is not an expense, so no IS impact. Only interest hits the IS.");
C(T,2,"A company issues $100 of stock to buy equipment. Walk it through.","PP&E +100, equity +100, no cash moves.\n- Non-cash transaction, so it is disclosed but not on the CFS.");
C(T,2,"A $100 convertible bond converts into stock. Walk it through.","Debt -100, equity +100, no cash and no IS impact.\n- Future interest expense goes away; share count rises.");
C(T,3,"A company loses $100 pretax. Tax rate 25%. What happens to taxes?","No tax paid now; it creates an NOL worth up to $25 of future tax savings.\n- If future use is likely, book a DTA of 25 and a tax benefit on the IS.\n- If not, a valuation allowance offsets it.");
C(T,1,"What does a 2-for-1 stock split do to the statements?","Nothing economic.\n- Shares double, price halves.\n- Equity value, cash and earnings are unchanged; EPS halves.");
C(T,3,"Explain operating versus finance leases under ASC 842.","Both are on the balance sheet; they differ on the IS.\n- Operating lease: one straight-line rent expense above EBITDA.\n- Finance lease: depreciation plus interest, so EBITDA is higher.\n- In valuation, be consistent: if lease liabilities are debt, use EBITDAR.");
C(T,1,"What items sit between revenue and net income?","Revenue, COGS, gross profit, opex, EBIT, interest, taxes, net income.\n- Opex includes SG&A and R&D.\n- D&A is embedded in COGS or opex.");
C(T,1,"Name some items in cash from operations.","Net income, non-cash items and working capital changes.\n- D&A, SBC, deferred taxes, impairments, gains on sale.\n- Changes in receivables, inventory, payables, deferred revenue, accruals.");
C(T,2,"Can EBITDA margin be higher than gross margin?","Yes, when D&A sitting inside COGS is bigger than cash operating expenses.\n- EBITDA adds back the D&A that gross profit already deducted.\n- Think capital-heavy business with tiny SG&A.");
C(T,2,"When could net income equal EBITDA?","Only if D&A, interest and taxes are all zero or net out.\n- No debt, no assets to depreciate, no tax. Rare in practice.");
C(T,3,"How can levered free cash flow be higher than EBITDA?","Large working capital inflows or other cash not in EBITDA.\n- Big deferred revenue or payables build.\n- Tax refunds or interest income.\n- It is usually temporary.");
C(T,1,"Accounts receivable rise by $50. What happens to cash flow?","Cash from operations is $50 lower than net income.\n- Revenue was recorded but the cash has not been collected.");
C(T,2,"A company accrues a $20 bonus it has not paid. Tax rate 25%. Walk it through.","Net income -15, cash +5.\n- Expense 20, tax saving 5, NI -15.\n- CFS: NI -15 + accrued liabilities +20 = +5.\n- BS: cash +5; accrued liabilities +20, retained earnings -15.");
C(T,2,"A company prepays $12 for a year of insurance. What happens now and each month?","Today: cash -12, prepaid asset +12. Each month: expense 1.\n- The prepaid asset is used up as the coverage period passes.\n- CFS shows the 12 outflow upfront in working capital.");
C(T,2,"What is the difference between depreciation and amortization?","Same idea, different assets.\n- Depreciation: tangible assets like PP&E.\n- Amortization: intangibles like patents or acquired customer lists.");
C(T,2,"What goes into operating working capital and what stays out?","Operating current assets minus operating current liabilities.\n- In: receivables, inventory, prepaids, payables, accruals, deferred revenue.\n- Out: cash and debt, since those are financing items.");
C(T,3,"A company starts capitalizing software development costs instead of expensing them. What happens to EBITDA, net income and free cash flow?","EBITDA up, net income up near term, free cash flow unchanged.\n- The spend moves from opex to capex.\n- Cash spent is the same, just shown in investing instead of operating.");
C(T,2,"What are the five steps of revenue recognition under ASC 606?","Contract, obligations, price, allocate, recognize.\n- Identify the contract and the performance obligations.\n- Set the transaction price and allocate it across obligations.\n- Recognize revenue as each obligation is satisfied.");
C(T,3,"A company buys 60% of another company. What shows up in its financials?","It consolidates 100% of the target and shows the other 40% as NCI.\n- Revenue, EBITDA, assets and liabilities come in at 100%.\n- NCI sits in equity; NCI's share of profit is subtracted below net income.");
C(T,2,"A company owns 30% of another company. How is it accounted for?","Equity method.\n- One line investment on the balance sheet.\n- Its share of the investee's net income shows as equity income.\n- Revenue and EBITDA of the investee are not consolidated.");
C(T,1,"What are the ownership thresholds for accounting treatment?","Under 20%: fair value. 20 to 50%: equity method. Over 50%: consolidate.\n- The real test is control and significant influence, not just the percentage.");
C(T,1,"Why is EBITDA not the same as cash flow?","It ignores capex, working capital, interest and taxes.\n- A capital-heavy business can have big EBITDA and little cash.");
C(T,2,"Deferred revenue is rising quickly. Good or bad?","Usually good.\n- Customers are paying upfront, which funds the business.\n- For SaaS it signals billings growth ahead of revenue.");
C(T,1,"What is a sale-leaseback and why do one?","Sell an owned asset and lease it back.\n- Raises cash immediately while keeping use of the asset.\n- Trade-off: ongoing lease payments.");
C(T,2,"What does operating leverage mean, and why does it matter?","The share of costs that are fixed.\n- High operating leverage: profit grows faster than revenue on the way up.\n- It also falls faster on the way down.");
C(T,4,"A streaming company buys a 5-year license for $200M, funded 75% debt at 10% PIK and 25% cash. 1M subscribers at $5/month, collected upfront. It spends $30M on marketing over 3 years. Ignore tax. Walk through year 1.","Pretax income -5, change in cash 0.\n- IS: revenue 60, license amortization 40, marketing 10, PIK interest 15, pretax -5.\n- CFS: -5 + 40 + 15 = 50 from operations; -200 license; +150 debt; net 0.\n- BS: license 160 = debt 165 + retained earnings -5.\n- Assumes marketing is paid 10 a year. If all 30 is prepaid, cash is -20 and a 20 prepaid asset appears.");
C(T,2,"Inventory is written down by $10. Tax rate 25%, deductible. Walk it through.","Net income -7.5, cash +2.5.\n- COGS or a charge of 10, tax saving 2.5.\n- CFS: add back the non-cash 10.\n- BS: inventory -10, cash +2.5; retained earnings -7.5.");
C(T,3,"A company records $100 of revenue on credit, then the customer never pays. Ignore tax. What happens?","Revenue and AR go up, then a bad debt expense wipes it out.\n- Net income ends at 0 (100 revenue, 100 bad debt).\n- No cash ever comes in; AR ends at 0.");
C(T,2,"Why does a fast-growing, profitable company often burn cash?","Growth soaks up cash before it comes back.\n- Inventory and receivables build ahead of sales.\n- Capex for capacity comes before the revenue it supports.");

})();

// ---- comps.js
;(function(){
var T="Comps";
C(T,1,"Walk me through a trading comps analysis.","Value the company like its listed peers.\n- Pick peers on industry, size, growth, margins.\n- Compute multiples (EV/EBITDA, EV/Revenue, P/E).\n- Apply the median or a chosen range to the target's metric, then bridge to price.");
C(T,1,"Walk me through a precedent transactions analysis.","Value the company on what buyers paid for similar companies.\n- Pick recent, relevant deals.\n- Compute deal multiples like EV / LTM EBITDA.\n- Apply them; values come out higher because of the control premium.");
C(T,2,"Why is there a control premium in precedent transactions?","Buyers pay for control.\n- Control means directing strategy, cash and capital structure, and capturing synergies.\n- Typically 20 to 40% over the unaffected price.");
C(T,2,"Which usually gives a higher valuation: comps or precedents? When is that reversed?","Precedents, because of the control premium.\n- Reversed when markets are hot today but past deals were done in weak markets or were distressed.");
C(T,2,"How do you choose comparable companies?","Business model first, then financial profile.\n- Same industry and customers.\n- Similar size, growth, margins, geography.\n- Start broad, then tighten.");
C(T,2,"Four of your seven comps are weak matches. What do you do?","Lean on the best three or four.\n- Show the full range and median for reference.\n- Justify a premium or discount from growth, margins and scale.");
C(T,2,"Which multiple would you use and when?","Pick the one that captures how the business makes money.\n- EV/EBITDA for mature, profitable companies.\n- EV/Revenue for high growth or unprofitable.\n- P/E for financials and stable earners; sector metrics where they fit.");
C(T,2,"Should a software company be valued on EV/Revenue or EV/EBITDA?","Depends on maturity.\n- Growth-stage, unprofitable: EV/Revenue or EV/ARR.\n- Mature and profitable: EV/EBITDA or EV/FCF.");
C(T,2,"Why value some SaaS companies on free cash flow multiples instead of EBITDA?","EBITDA can overstate their cash.\n- Capitalized software, SBC and deferred revenue swings distort it.\n- FCF shows real cash conversion.");
C(T,2,"Why pair EV with revenue and price with earnings?","Match the claimant.\n- Revenue funds all capital providers, so EV.\n- Earnings are what is left for shareholders, so price.");
C(T,2,"What are the limitations of EV/EBITDA?","It ignores cash needs.\n- Capex and working capital are left out.\n- Distorted by SBC, leases and D&A policy.\n- Meaningless when EBITDA is negative.");
C(T,2,"Why is EBITDA so widely used for valuation?","It is a rough proxy for operating cash flow.\n- Before capital structure, tax and D&A choices, so it compares well across companies.");
C(T,3,"Why might Buffett prefer EV/EBIT over EV/EBITDA?","D&A is a real economic cost.\n- Assets wear out and must be replaced.\n- EBIT is closer to true owner earnings for capital-heavy businesses.");
C(T,2,"Two similar companies trade at different EV/EBITDA multiples. Why?","Different expected growth, margins, risk or return on capital.\n- Also scale, customer quality, management.\n- Or EBITDA quality: one-offs and SBC add-backs.");
C(T,3,"Two companies have the same EV/EBITDA but different P/E ratios. Why?","Differences below EBITDA.\n- Leverage (interest), D&A, tax rates.");
C(T,2,"Two companies trade at 2x revenue; one is 6x EBITDA, the other 10x. What does that tell you?","The 6x company has higher margins.\n- Margin = EV/Rev / EV/EBITDA: 33% versus 20%.\n- The market pays the same per dollar of revenue.");
C(T,3,"Company A grows 30% with a 10% margin; B grows 10% with a 30% margin. Which deserves the higher multiple?","Depends on the multiple.\n- On revenue, A usually gets more for its growth.\n- On EBITDA, A's multiple is higher too, since its earnings are small today but growing fast.\n- Rule of 40 treats them as equal.");
C(T,2,"LTM or NTM multiples: when do you use each?","NTM for growing companies; LTM for stable ones and for precedents.\n- Forward multiples reflect what the market is pricing.\n- Deal multiples are usually quoted on LTM because that is what is known at signing.");
C(T,2,"What is calendarization?","Lining everyone up on the same fiscal period.\n- e.g. CY2025 = half of FY June 2025 + half of FY June 2026.");
C(T,1,"Why use the median rather than the mean for a comps set?","Outliers.\n- One extreme multiple can skew the mean.");
C(T,2,"When would you not rely on precedent transactions?","When deals are few, old or unusual.\n- Different market regime or rate environment.\n- Distressed sales or minority stakes.");
C(T,2,"How does a premiums analysis differ from precedent transactions?","Premiums uses the percentage paid over the unaffected price; precedents uses the multiple paid.\n- Premiums: apply typical premium to the target's share price.\n- Precedents: apply the deal multiple to the target's EBITDA.");
C(T,2,"Can you use private companies as comps?","Not for trading comps or beta: they have no market price.\n- Private deals can be used as precedent transactions.");
C(T,3,"Your valuation is too high. What would you adjust in each method?","Make the inputs more conservative.\n- DCF: lower growth or margins, raise WACC.\n- Comps: tighter peer set, lower point in the range.\n- Precedents: drop synergy-heavy or old deals.");
C(T,2,"When should one-time charges be added back to EBITDA?","Only when they are truly non-recurring.\n- Restructuring, litigation, impairments.\n- Be skeptical of 'one-offs' that happen every year.");
C(T,3,"What multiples work for pre-revenue biotechs?","None of the normal ones.\n- EV versus cash, EV per pipeline asset, EV / risk-adjusted peak sales.\n- Compare to deal values for similar-stage assets.");
C(T,3,"What is the link between price-to-book and ROE?","P/B = (ROE - g) / (Ke - g).\n- Earning above the cost of equity justifies trading above book.\n- Used for banks and insurers.");
C(T,3,"A stock pays a 4% dividend yield and grows 10% forever. What return does that imply?","14%.\n- Required return = dividend yield + growth.");
C(T,2,"What is a football field?","A chart of valuation ranges from each method side by side.\n- DCF, comps, precedents, LBO, 52-week range.\n- Shows where a proposed price sits.");
C(T,2,"What multiples do banks, REITs and E&P companies trade on?","Sector-specific multiples.\n- Banks: P/E, P/B, P/TBV.\n- REITs: P/FFO, P/AFFO, cap rates, NAV.\n- E&P: EV/EBITDAX, EV per reserves or production.");
C(T,2,"What multiple would you use for a retailer with lots of leased stores?","EV/EBITDAR.\n- Rent is effectively a financing cost.\n- Add rent back and include lease liabilities in EV for consistency.");
C(T,2,"What is the unaffected share price?","The price before deal news or rumors leaked.\n- Premiums should be measured from it, not the run-up price.");
C(T,2,"A comp has negative EBITDA. What do you do with its EV/EBITDA?","Mark it NM (not meaningful) and exclude it.\n- A negative multiple tells you nothing.");
C(T,3,"What is a sum-of-the-parts valuation and when is it used?","Value each segment separately, then add them up.\n- For conglomerates whose units deserve different multiples.\n- Subtract unallocated corporate costs and net debt.");
C(T,2,"What is the PEG ratio?","P/E divided by growth rate.\n- Adjusts P/E for growth; around 1x is often called fair.");
C(T,2,"Why do growth companies trade at higher multiples?","Today's earnings are small relative to future earnings.\n- The multiple prices in that future growth.");
C(T,2,"A company trades at 10x EBITDA. What does that roughly mean?","Buyers pay ten years of current EBITDA for the business.\n- Equivalent to a 10% EBITDA yield on EV, before capex, tax and growth.");
C(T,3,"How do you reflect market sentiment in a comps analysis?","Compare current multiples to their history.\n- Note where the sector sits versus its range.\n- Lean on forward multiples, which carry current expectations.");
C(T,3,"Is EV/subscribers or EV per user a valid multiple?","Yes, if it drives economics and is defined the same way across comps.\n- Check paying versus total users, churn and revenue per user.");
C(T,2,"What is a merger versus an acquisition?","Mostly legal and optics.\n- Merger: two companies combine, often framed as equals.\n- Acquisition: one buys the other, which becomes a subsidiary or disappears.");
C(T,3,"What is a reverse triangular merger and why use it?","A buyer's subsidiary merges into the target, and the target survives.\n- Keeps the target's contracts, licenses and permits intact.\n- Avoids consents an asset transfer would need.");

})();

// ---- dcf.js
;(function(){
var T="DCF";
C(T,1,"Walk me through a DCF.","Value = present value of future cash flows.\n- Project unlevered free cash flow for 5 to 10 years.\n- Add a terminal value (Gordon growth or exit multiple).\n- Discount everything at WACC to get EV, then bridge to equity value and price per share.");
C(T,1,"Walk me from revenue to unlevered free cash flow.","Revenue to EBIT, tax it, add back non-cash, subtract reinvestment.\n- EBIT x (1 - t) = NOPAT.\n- Add D&A and other non-cash charges.\n- Subtract capex and the increase in net working capital.");
C(T,1,"What is the difference between unlevered and levered free cash flow?","Before versus after debt holders get paid.\n- UFCF: before interest, belongs to all capital providers, discount at WACC to get EV.\n- LFCF: after interest and debt repayment, belongs to equity, discount at cost of equity to get equity value.");
C(T,2,"Why do most DCFs use unlevered free cash flow?","It keeps the valuation independent of capital structure.\n- Comparable across companies with different leverage.\n- Avoids modeling a full debt schedule.");
C(T,2,"How do you get from unlevered to levered free cash flow?","Subtract after-tax interest and net debt repayments.\n- Interest x (1 - t) comes out.\n- Mandatory repayments come out, new borrowing goes in.");
C(T,1,"What discount rate goes with each type of free cash flow?","UFCF with WACC, LFCF with cost of equity.\n- Match the rate to the people who own that cash flow.");
C(T,2,"Why do we tax EBIT rather than EBT in unlevered free cash flow?","To keep financing out of the cash flow.\n- The interest tax shield is captured in WACC through Kd x (1 - t).\n- Taxing EBT would count it twice.");
C(T,2,"Should interest income on cash be in unlevered free cash flow?","No.\n- Cash is added back in the EV to equity bridge.\n- Counting its interest too would double count it.");
C(T,2,"Walk me through terminal value and the two methods.","Terminal value captures everything after the forecast.\n- Gordon growth: FCF next year / (WACC - g).\n- Exit multiple: final-year EBITDA x a peer multiple.\n- Discount it back with the final-year discount factor.");
C(T,2,"Why use one terminal value method over the other?","Gordon is intrinsic, exit multiple is market-based.\n- Gordon suits stable, mature companies.\n- Exit multiple is simpler when comps are good.\n- Best practice: back out the implied multiple or implied growth and check both make sense.");
C(T,3,"How do you back out implied perpetuity growth from an exit-multiple terminal value?","g = (TV x WACC - FCF) / (TV + FCF).\n- FCF is the final-year cash flow.\n- If g comes out above roughly 3 to 4%, the exit multiple is too aggressive.");
C(T,2,"Why must the terminal growth rate be below WACC?","The formula breaks otherwise.\n- At g = WACC value is infinite; above it, negative.\n- A company cannot outgrow its cost of capital forever.");
C(T,2,"What is a reasonable terminal growth rate, and why?","Roughly 2 to 3%, around long-run inflation or GDP.\n- Anything above long-run GDP implies the company eventually becomes the economy.");
C(T,2,"Terminal value is 80% of your DCF. Is something wrong?","Not necessarily.\n- 60 to 80% is normal, especially for growth companies.\n- It is a flag if the forecast ends before the business reaches steady state.");
C(T,2,"How can you reduce terminal value's share of a DCF without changing core assumptions?","Extend the forecast.\n- Add a fade period so growth and margins reach steady state before the terminal year.");
C(T,2,"What should the terminal year look like?","A normalized steady state.\n- Stable margins and growth.\n- Capex near or slightly above D&A.\n- Working capital growing in line with revenue.");
C(T,2,"Should you use mid-year or end-of-year discounting?","Mid-year if cash comes in through the year, which is more realistic.\n- It gives a slightly higher value.\n- Exit-multiple terminal value is still discounted at the full year-end period.");
C(T,2,"How does a higher tax rate affect a DCF?","Lower value overall.\n- UFCF falls because NOPAT falls.\n- After-tax cost of debt rises, so WACC rises slightly.\n- Terminal value falls with both.");
C(T,2,"How do higher interest rates affect a DCF?","Lower value.\n- Risk-free rate up pushes cost of equity and cost of debt up, so WACC rises.\n- Terminal value, the most distant cash flow, is hit hardest.");
C(T,3,"How do higher interest rates affect a DCF, trading comps and precedents differently?","DCF moves directly; comps move with the market; precedents lag.\n- DCF: WACC rises right away.\n- Comps: multiples compress as the market reprices.\n- Precedents: struck in older rate environments, so they become less relevant.");
C(T,3,"Which moves a DCF more: 1% on WACC or 1% on terminal growth?","Usually WACC.\n- It hits every discount factor and the terminal value denominator.\n- Growth only affects terminal value.");
C(T,2,"Which raises free cash flow most: $10 more revenue (no cost), $10 less opex, or $10 less capex?","Capex.\n- Capex savings drop straight to cash.\n- Revenue and opex both raise EBIT by 10, which then gets taxed, so cash rises by 10 x (1 - t).");
C(T,2,"How does an increase in accounts payable affect free cash flow?","It raises free cash flow.\n- You are holding onto cash longer before paying suppliers.");
C(T,2,"How does higher projected capex affect a DCF?","Lower FCF now, and it should mean higher revenue later.\n- If you raise capex, make sure the revenue forecast reflects the growth it buys.");
C(T,2,"How long should the projection period be?","5 to 10 years.\n- Long enough for the business to reach steady state.\n- Longer for high-growth or pre-profit companies.");
C(T,2,"When is a DCF most and least useful?","Best for stable, predictable cash flows; worst for early-stage or very cyclical businesses.\n- Least useful when cash flows are negative for years or terminal value is nearly all of the value.");
C(T,3,"How would you build a DCF for a company with negative EBITDA today?","Forecast long enough to reach positive, steady-state margins.\n- Build up revenue growth and margin ramp explicitly.\n- Use a higher discount rate and lean on sensitivities, since terminal value will dominate.");
C(T,3,"Can a company have negative EBITDA but positive unlevered free cash flow?","Yes, temporarily.\n- Large working capital inflows such as customer prepayments.\n- Tax refunds or asset sales.");
C(T,2,"What are the main weaknesses of a DCF?","Very sensitive to assumptions.\n- Small changes in WACC or growth swing value a lot.\n- Terminal value often dominates.\n- It ignores what the market will actually pay.");
C(T,3,"Why might a DCF come out higher than precedent transactions?","Optimistic projections.\n- DCFs often run on management cases.\n- Precedents reflect what buyers actually paid in past markets.");
C(T,3,"How do you factor NOLs into a DCF?","Use them to reduce cash taxes in the forecast years.\n- Cap annual usage under Section 382.\n- Or value the tax shield separately. Not both.");
C(T,3,"How would you value a company planning a major acquisition in year 3?","Value the standalone business, then add the deal separately.\n- Deal NPV = PV of target cash flows plus synergies minus price.\n- Or model it inside, with the financing and capital structure updated.");
C(T,2,"Should stock-based compensation be treated as a cash expense in a DCF?","Treat it as a real cost.\n- Do not add it back; it is paid in dilution.\n- If you add it back, you must count the future dilution in the share count.");
C(T,2,"How do you treat amortization of intangibles in a DCF?","Add it back as non-cash, but keep its tax effect if deductible.\n- Taxes are computed on EBIT after amortization.");
C(T,3,"What is APV and when would you use it?","Adjusted present value: unlevered value plus the value of financing effects.\n- Discount UFCF at the unlevered cost of equity.\n- Add the PV of interest tax shields.\n- Useful when leverage changes a lot over time, like an LBO.");
C(T,3,"When does a dividend discount model make more sense than a DCF?","For banks and insurers.\n- Debt is their raw material, not a financing choice.\n- So value cash flows to equity: dividends discounted at cost of equity.");
C(T,3,"How do you value a cyclical company with a DCF?","Normalize to mid-cycle.\n- Use average margins across the cycle, not peak or trough.\n- Make sure the terminal year is not a peak year.");
C(T,2,"What happens to DCF value if every cash flow arrives a year later?","Value falls by about one year of discounting.\n- Roughly divide by (1 + WACC).");
C(T,3,"What is a reverse DCF?","Solve for the assumptions the current price implies.\n- Fix the price and WACC, back out growth or margins.\n- Then ask whether those expectations are realistic.");
C(T,3,"Two DCFs give the same EV. One gets 50% from terminal value, the other 80%. Which is riskier?","The 80% one.\n- More value sits far in the future.\n- It is more sensitive to WACC and growth assumptions.");
C(T,3,"Current share price is $100, DCF value is $100, discount rate 10%. What return do you expect?","About 10%.\n- Buying at intrinsic value earns your cost of capital, nothing extra.");
C(T,3,"A project costs $80M and generates $25M a year for 5 years. What is NPV at 10%?","About $14.8M.\n- 5-year annuity factor at 10% is 3.79.\n- 25 x 3.79 = 94.8; minus 80 = 14.8.");
C(T,3,"Next year's FCF is $100M, WACC 10%, growth 3%. What is the Gordon growth value?","About $1,429M.\n- 100 / (0.10 - 0.03) = 1,428.6.");
C(T,2,"What is NPV and how does it relate to IRR?","NPV is the PV of all cash flows; IRR is the rate that makes NPV zero.\n- If IRR beats the required return, NPV is positive.");
C(T,1,"What is the difference between CAGR and IRR?","CAGR only looks at start and end values.\n- IRR accounts for every interim cash flow and its timing.");
C(T,2,"What is the difference between IRR and ROI?","IRR is annualized and time-weighted; ROI is not.\n- ROI = gain / cost, ignoring how long it took.");
C(T,2,"Should you include acquisitions in a DCF forecast?","Only if you include both sides.\n- If revenue growth assumes acquisitions, include the acquisition spend as cash out.\n- Otherwise use organic growth only.");
C(T,2,"Why is the cash flow used in Gordon growth next year's, not the final year's?","The formula values a stream starting one period ahead.\n- TV at year N = FCF in year N+1 / (WACC - g).");
C(T,3,"How do you convert a Gordon growth terminal value into an implied exit multiple?","Divide TV by final-year EBITDA.\n- If it is far above peer multiples, your growth or WACC is off.");
C(T,2,"Which two inputs usually go in a DCF sensitivity table?","WACC and terminal growth, or WACC and exit multiple.\n- They are the biggest drivers of value.");

})();

// ---- dealbook.js
;(function(){
var T="Deal Book";
C(T,3,"Radiopharma: why is isotope supply a stronger moat than the molecule? Where does it break?","Scarce, decaying isotopes gate who can deliver therapy.\n- Lu-177 and Ac-225 are hard to make and decay in days.\n- A great molecule without supply cannot reach patients.\n- Breaks if new producers commoditize supply.","Scarcity vs commoditization risk.");
C(T,3,"Lu-177 vs Ac-225: how would you value an Ac-225 asset differently?","More upside, more risk.\n- Alpha emitter: more potent, may work after Lu-177 failure.\n- Scarcer supply and toxicity risk lower PoS.\n- BMS RYZ101 meeting its endpoint after Lu-177 raised confidence in the class.","Alpha potency vs toxicity and supply.");
C(T,3,"Why did Lantheus sell to Curium, and what would the standalone case have needed?","A maturing franchise facing competition, sold at an attractive price.\n- Pylarify faces PSMA PET rivals.\n- Standalone needed durable share, neurology growth and pipeline wins.\n- Deal: $102.50 cash plus up to $12 in CVRs.","Mature franchise facing competition.");
C(T,3,"How would you build a peak sales model for a PSMA therapy?","Patients x penetration x net price x duration.\n- Patients: prostate cancer settings, PSMA-positive share, line of therapy.\n- Penetration: competition, nuclear medicine capacity, isotope supply.\n- Then risk-adjust and time launches by setting.","Patients x penetration x net price x duration.");
C(T,3,"A big pharma wants into radiopharma. Buy a platform, buy a supplier or license assets?","Trade time, control and cost.\n- Platform: fastest scale, expensive (BMS paid about $4.1B for RayzeBio).\n- Supplier: secures the bottleneck (Telix/ITM logic).\n- License: cheap and flexible, less control (Novartis/Zonsen, $50M upfront).","Time-to-market vs control vs cost.");
C(T,3,"Why do diagnostics companies have strategic value in radiopharma?","They pick the patients.\n- The diagnostic PET scan identifies who expresses the target.\n- That drives referrals into the paired therapy.","Theranostic pairing.");
C(T,3,"Why is China a source of radioligand assets, and what are the risks?","Speed and cost.\n- Fast, cheap early development (Novartis/BoomRay up to $900M).\n- Risks: FDA acceptance of data, supply logistics, geopolitics.","Cost and speed vs data and policy risk.");
C(T,3,"A manufacturing CRL hits a target you advise. How does structure change?","Shift the CMC risk.\n- CVRs tied to approval, escrow or a lower upfront.\n- Closing conditions tied to resubmission.\n- Telix/ITM did exactly this.","CVR or escrow to allocate CMC risk.");
C(T,3,"Curium/Lantheus: how should you read the premium?","The headline flatters it.\n- $114.50 total is about 38% over the 60-day unaffected VWAP.\n- Cash at close alone is only about 8% above the unaffected price.\n- The rest depends on 2030 revenue CVRs.");
C(T,3,"Telix/ITM: what is the structure?","$1.65B upfront plus up to $700M of CVRs.\n- Upfront: $1.25B Telix stock, $302M assumed net debt, $96M rollover.\n- CVR: $250M regulatory, $450M sales-based.\n- About 6x ITM's 2025 supply revenue before crediting ITM-11.");
C(T,3,"Cancer vaccines: why doesn't a melanoma win guarantee success in lung cancer?","Different biology and trial setup.\n- Melanoma has high mutation burden and responds to checkpoints.\n- Lung differs in microenvironment, standard of care and design.","Microenvironment, mutation burden, standard of care.");
C(T,3,"How would you risk-adjust intismeran across melanoma, NSCLC, bladder and RCC?","Separate PoS and market for each.\n- Melanoma: highest PoS after the Phase 3 win.\n- Others: lower PoS by stage and data.\n- Sum the indication rNPVs.","Separate PoS and market size per indication.");
C(T,3,"How do you value a company that is mostly one partnered asset, like Moderna?","Sum of the parts.\n- rNPV of the asset at its economics (50% profit share).\n- Plus the rest of the pipeline and cash, minus burn.\n- A 50% share transforms Moderna but barely moves Merck.","Sum-of-the-parts rNPV.");
C(T,3,"INTerpath-001 effect size is undisclosed. What would you need to see?","The numbers behind 'positive'.\n- Hazard ratio, absolute recurrence rates, event counts.\n- Subgroup consistency, distant metastasis and survival trends, safety.","HR, absolute rates, events, subgroups, OS.");
C(T,3,"How should a payer think about a $400K+ one-time personalized therapy added to Keytruda?","Cost versus avoided recurrence.\n- Compare to metastatic treatment costs and QALYs gained.\n- Outcomes-based or installment contracts can align payment to benefit.","Value-based pricing, budget impact.");
C(T,3,"Why is manufacturing turnaround a commercial issue for an individualized vaccine?","The treatment window is short.\n- Slow turnaround after surgery shrinks the eligible patients.\n- Cost of goods and scale set margins.","Time from surgery to first dose.");
C(T,3,"Merck splits costs and profits 50/50 with Moderna. When is that good for the smaller partner and when a trap?","Good for resources, costly in control.\n- Good: big-pharma muscle, shared costs.\n- Trap: half the economics, less control, and 50% of costs can be heavy as trials expand.","Funds fewer costs but gives up control and upside.");
C(T,3,"Who is the buyer universe for a neoantigen platform?","Checkpoint franchise owners facing patent cliffs.\n- Merck, BMS, AstraZeneca, Roche, plus platform players.\n- Mostly partnerships so far; a Phase 3 win could change that.","Pharma with checkpoint franchises.");
C(T,3,"HAE: if one-time lonvo-z is approved, who loses revenue and how fast?","Chronic prophylaxis incumbents lose switchers.\n- 87% attack reduction, 62% attack-free off therapy.\n- About 20% of patients switch yearly, so uptake can be quick.\n- Pace depends on price, durability and safety.","Who switches to a one-time cure vs who stays.");
C(T,3,"How do you compare a one-time therapy with a chronic therapy of the same total cost?","Net present cost and durability.\n- One-time cash upfront is worth more to the seller in NPV.\n- Durability uncertainty pushes payers to installments or outcomes deals.","Net present cost, durability, payment models.");
C(T,3,"Why can a small rare disease market support $1B+ deals?","High price per patient, concentrated prescribers.\n- About 6,000 US HAE patients at high annual prices.\n- A small salesforce reaches allergists and immunologists.","Ultra-high price, concentrated prescribers.");
C(T,3,"In an HAE switch market with about 20% annual switching, how do you model share?","Switchers captured plus new starts.\n- Switch rate x your share of switchers.\n- Convenience and efficacy drive capture.","Switch rate x capture x incumbency.");
C(T,3,"Why did Chiesi pay $1.9B for KalVista with only $49M of 2025 sales?","Peak sales and a platform.\n- Price rests on rNPV of oral on-demand Ekterly.\n- Also buys a US rare disease commercial base.\n- 36% premium on a stock already up about 75%.","Peak sales x probability x time.");
C(T,3,"BioCryst/Astria: why mixed cash and stock, and what does the Blackstone facility signal?","Preserve cash, at the cost of leverage.\n- About $700M at $13/share, 53% premium.\n- About $396.6M drawn from a Blackstone facility adds fixed obligations.\n- Signals reliance on private credit.","Avoids dilution, adds fixed obligations.");
C(T,3,"Pharvaris has positive data in both settings. Who is the best buyer and how would you price it?","A pharma wanting an oral HAE franchise.\n- Incumbents or new entrants with commercial reach.\n- Price off rNPV plus precedent premiums (KalVista 36%, Astria 53%).\n- PDUFAs in 2027, runway into 2028.","Combined franchise, existing infrastructure.");
C(T,3,"How do icatibant generics affect on-demand pricing?","They cap it.\n- Payers have a cheap option, so new entrants need clear benefits like oral dosing.","Price erosion in on-demand.");
C(T,3,"Why do CVRs keep appearing in these deals, and how do you value them?","They bridge valuation gaps and shift risk.\n- Value each tier at probability x payout, discounted.\n- Compare headline versus risk-adjusted price.");
C(T,3,"Compare premiums: KalVista 36%, Astria 53%, Lantheus 21 to 38% headline (about 8% cash-only). Why the differences?","Different reference prices and structures.\n- 30-day VWAP versus prior close versus unaffected VWAP.\n- Single-asset biotechs command more than a mature diagnostics franchise.\n- CVRs inflate headline premiums.");

})();

// ---- debt.js
;(function(){
var T="Debt";
C(T,2,"Rank a typical capital structure from most to least senior.","Revolver and term loans, second lien, senior notes, subordinated notes, preferred, common.\n- Higher seniority means lower yield and tighter terms.");
C(T,1,"Why does secured debt trade tighter than unsecured?","Collateral.\n- Higher expected recovery in default, so lenders need less spread.");
C(T,1,"$150M of debt and $50M of EBITDA. What is leverage?","3.0x.\n- Debt / EBITDA.");
C(T,2,"Leverage is 10x EBITDA and the cost of debt is 10%. What is interest coverage?","1.0x.\n- Interest = 10 x 10% = 1x EBITDA.\n- EBITDA barely covers interest, before capex and tax: distressed.");
C(T,3,"$200 first lien, $150 second lien, $100 unsecured. What does each recover at EV of $500, $400 and $300?","Fill from the top down.\n- $500: all paid in full, $50 to equity.\n- $400: first and second in full, unsecured gets 50%.\n- $300: first in full, second gets 100 of 150 (67%), unsecured nothing.");
C(T,3,"A 5% coupon bond yields 10% with 5 years left. What is its price?","About $81 per $100.\n- Coupons: 5 x 3.79 annuity factor = 18.95.\n- Principal: 100 / 1.1^5 = 62.1.");
C(T,1,"Why do bond prices fall when yields rise?","Fixed coupons become less attractive.\n- The price must fall until the yield matches the market.");
C(T,2,"Which is more sensitive to rates: a zero-coupon bond or a coupon bond of the same maturity?","The zero.\n- All cash comes at maturity, so its duration is longest.");
C(T,2,"What is duration?","Price sensitivity to rates.\n- Roughly the % price change for a 1% move in yield.\n- Longer maturity and lower coupon mean higher duration.");
C(T,2,"What is the difference between a revolver, a term loan A and a term loan B?","Different lenders and repayment profiles.\n- Revolver: draw and repay as needed, commitment fee on unused amount.\n- TLA: banks, amortizes meaningfully.\n- TLB: institutional investors, about 1% a year, bullet at maturity.");
C(T,2,"What is call protection?","A period when the issuer cannot repay early, or must pay a premium.\n- Protects bondholders from refinancing when rates fall.");
C(T,2,"What is a make-whole call?","Early repayment at the PV of remaining payments.\n- Discounted at Treasuries plus a small spread, so it is expensive for the issuer.");
C(T,1,"What is the investment grade cutoff?","BBB- (S&P/Fitch) or Baa3 (Moody's).\n- Below that is high yield.");
C(T,2,"What is the absolute priority rule?","In bankruptcy, senior claims are paid in full before junior claims get anything.");
C(T,2,"What is the difference between Chapter 11 and Chapter 7?","Reorganize versus liquidate.\n- Chapter 11: the company keeps operating and restructures.\n- Chapter 7: assets are sold and proceeds paid out.");
C(T,2,"What is DIP financing?","New money lent to a company in Chapter 11.\n- Funds operations during the case.\n- Super-priority, paid ahead of existing debt.");
C(T,3,"What is the fulcrum security?","The most senior class that is not paid in full.\n- It usually becomes the new equity in a restructuring.");
C(T,2,"What is the difference between coupon and yield?","Coupon is fixed on face value; yield is the return at today's price.\n- Price below par means yield above coupon.");
C(T,3,"Why would a company issue convertible bonds?","Cheaper interest in exchange for equity upside.\n- Lower coupon than straight debt.\n- Dilution only if the stock rises past the conversion price.");
C(T,3,"Besides leverage and interest coverage, what shows how much debt a company can handle?","Fixed charge coverage and free cash flow to debt.\n- (EBITDA - capex) / interest shows true debt service capacity.");
C(T,3,"How does fixed versus floating rate debt change a company's risk?","Floating-rate interest rises with rates.\n- That cuts free cash flow when rates go up.\n- Companies hedge with swaps or caps.");
C(T,3,"As a sole lender to a struggling company, when would you agree to switch interest to PIK?","When the problem is temporary and the business is viable.\n- In return, ask for a higher rate, more security, tighter covenants or warrants.");
C(T,3,"What happens to cost of debt when a company's rating improves?","It falls.\n- Lower default risk means tighter spreads.");
C(T,2,"What is a covenant-lite loan?","A loan with no maintenance covenants.\n- Only incurrence tests apply.\n- Standard in the TLB market.");
C(T,3,"Two identical companies, but one has convertible debt. Why might their equity values differ?","The convert holds an equity option.\n- It acts like debt plus a call option.\n- If the stock rises, holders convert and dilute common.");
C(T,3,"What is a distressed exchange?","Swapping existing debt for new securities worth less than face, outside court.\n- Avoids bankruptcy but usually counts as a default for ratings.");

})();

// ---- ev.js
;(function(){
var T="Enterprise Value";
C(T,1,"What is the difference between enterprise value and equity value?","Equity value is the shareholders' stake. Enterprise value is the core business, owned by all capital providers.\n- Equity value = share price x diluted shares.\n- EV = equity value + debt + preferred + NCI - cash.\n- Pair EV with pre-interest metrics (EBITDA) and equity value with post-interest metrics (net income).");
C(T,1,"How do you get from enterprise value to equity value?","Subtract debt, preferred and NCI, then add cash and non-operating assets.\n- Then divide by diluted shares to get price per share.");
C(T,1,"Why do we subtract cash when calculating enterprise value?","Cash is not part of the operating business.\n- A buyer effectively gets it back and could use it to pay down debt.\n- Exception: trapped or minimum operating cash is not really excess.");
C(T,2,"Why do we add non-controlling interest to enterprise value?","To match the consolidated metrics.\n- The parent reports 100% of the subsidiary's EBITDA but owns only part of it.\n- Adding NCI brings EV up to that same 100% basis.");
C(T,2,"Why do we subtract equity-method investments from enterprise value?","Their earnings are not in EBITDA.\n- They sit below the operating line as equity income.\n- So their value is non-operating and comes out of EV, just like cash.");
C(T,2,"Should you use the book or market value of debt in EV?","Market value in theory, book value in practice.\n- They are close unless the company is distressed.\n- For distressed debt trading far below face, use market value.");
C(T,2,"Can enterprise value be negative?","Yes, if cash is larger than equity value plus debt.\n- Seen in cash-rich biotechs where the market values the pipeline below zero.");
C(T,2,"Can equity value be negative?","No.\n- Shareholders have limited liability, so equity is worth at least zero.\n- If the business is worth less than its debt, equity is worth about zero.");
C(T,2,"EV is $200 and debt is $300. What is the equity value?","About zero, not -100.\n- The debt holders have a claim on the whole business.\n- Equity keeps only option value.");
C(T,2,"Can EV ever equal equity value?","Yes, when net debt and other claims are zero.\n- For example debt exactly equals cash, no preferred, no NCI.");
C(T,1,"A company issues $100 of new shares. What happens to EV and equity value?","EV unchanged, equity value +100.\n- Cash +100, so net debt -100.\n- The two changes offset in EV.");
C(T,1,"A company raises $100 of debt and holds the cash. What happens to EV and equity value?","Both unchanged.\n- Debt +100, cash +100, so net debt is flat.");
C(T,1,"A company repays $100 of debt with cash. What happens to EV?","No change.\n- Debt -100, cash -100, net debt flat.");
C(T,1,"A company uses $100 of cash to buy back shares. What happens to EV, equity value and share price?","EV unchanged, equity value -100, share price unchanged in theory.\n- Cash leaves, so net debt rises 100.\n- Fewer shares, lower equity value, same price per share.");
C(T,1,"A company pays a $100 cash dividend. What happens to EV and equity value?","EV unchanged, equity value -100.\n- Cash leaves, net debt +100.\n- The share price drops by the dividend per share.");
C(T,2,"A company issues $100 of new shares and uses the cash to repay debt. What happens?","EV unchanged, equity value +100, net debt -100.\n- Swapping debt for equity changes the mix, not the business.");
C(T,2,"A company borrows $100 and pays it out as a dividend. What happens to EV and equity value?","EV unchanged, equity value -100.\n- Debt +100 with no cash left behind, so net debt +100.\n- Value moves from shareholders to a claim held by lenders.");
C(T,3,"A company with $100 of EV issues $50 of stock and uses it to buy a business worth $50. What happens?","EV goes to $150, equity value +50, net debt unchanged.\n- New shares raise equity value.\n- Cash comes in and goes straight out.\n- The acquired business adds 50 of EV.");
C(T,2,"A company buys a business worth $80 using cash on hand. What happens to EV, net debt and equity value?","EV +80, net debt +80, equity value unchanged.\n- Cash out raises net debt.\n- The new operations add EV.");
C(T,3,"A company sells a division worth $100 at fair value and repays debt with the proceeds. What happens?","EV -100, net debt -100, equity value unchanged.\n- The operating business is gone, so EV falls.\n- Debt falls, so net debt falls.\n- Common mistake: saying net debt is flat because cash went in and out.");
C(T,3,"A company uses $100 of cash to buy a 30% stake in another company at fair value. What happens to EV?","EV unchanged.\n- Cash -100 raises net debt by 100.\n- But equity-method investments are subtracted in the EV bridge, so the two offset.\n- Equity value is also unchanged.");
C(T,3,"A company uses cash to buy a bond as an investment. What happens to EV and equity value?","Both unchanged.\n- Cash falls, investment rises by the same amount.\n- Both are non-operating, so both are subtracted in the bridge.");
C(T,3,"How do unfunded pension obligations affect enterprise value?","Add them as a debt-like claim.\n- The buyer inherits the obligation.\n- Often added on an after-tax basis, since contributions are deductible.");
C(T,3,"How do you treat NOLs in enterprise value?","Value them separately as future tax savings.\n- Value = NOL x tax rate, discounted and limited by Section 382.\n- Either subtract from EV like an asset or include in the DCF cash taxes. Do not do both.");
C(T,2,"Why is preferred stock added to enterprise value?","It is a senior claim ahead of common equity.\n- Fixed dividend and liquidation preference make it debt-like.");
C(T,2,"Why do we use EV with EBITDA but equity value with net income?","Match the numerator to who owns the metric.\n- EBITDA is before interest, so it belongs to all capital providers: EV.\n- Net income is after interest, so it belongs to shareholders: equity value.");
C(T,2,"What is wrong with EV/Net Income?","It mismatches claimants.\n- EV includes debt holders; net income is only for equity holders.\n- Use P/E instead.");
C(T,2,"If a company's capital structure changes, which moves more in theory: EV or equity value?","Equity value.\n- EV reflects the business and is capital-structure neutral in theory.\n- Equity value absorbs changes in net debt.");
C(T,1,"Why use diluted shares rather than basic shares?","Anyone who can become a shareholder will dilute the price.\n- In-the-money options, warrants, RSUs and convertibles all add shares.");
C(T,2,"Explain the treasury stock method.","Assume options are exercised and the strike proceeds buy back shares.\n- Only in-the-money options count.\n- Net new shares = options - (options x strike / price).\n- RSUs are added in full; ITM convertibles add conversion shares and remove the debt.");
C(T,2,"Why do out-of-the-money options not count in diluted shares?","No one would exercise them.\n- Paying more than the share price to get a share makes no sense.");
C(T,2,"If the share price rises, what happens to diluted shares under the TSM?","They go up.\n- More options move into the money.\n- Each option's proceeds buy back fewer shares at the higher price.");
C(T,3,"100 shares at $20, plus 20 options with a $10 strike. What is diluted equity value?","$2,200.\n- Proceeds 20 x 10 = 200 buy back 200 / 20 = 10 shares.\n- Net new shares 10, diluted shares 110.\n- 110 x 20 = 2,200.");
C(T,3,"Price $50. 500,000 shares, 200,000 options at $40, 100,000 RSUs. What is diluted equity value?","$32.0M.\n- Options: 200,000 - (200,000 x 40 / 50) = 40,000 net shares.\n- RSUs add 100,000.\n- 640,000 shares x $50 = $32.0M.");
C(T,3,"Price $40, 250M basic shares, 50M options at a $30 strike. How many diluted shares?","262.5M.\n- Proceeds buy back 50 x 30 / 40 = 37.5M shares.\n- Net new shares 12.5M.");
C(T,3,"A $20M convertible has a conversion price of $8 and the stock trades at $10. How do you treat it?","As converted: +2.5M shares and remove $20M of debt.\n- It is in the money because $10 > $8.\n- Out of the money, it would stay in debt.");
C(T,3,"How do you treat convertible preferred stock?","Like a convert: if in the money, assume conversion.\n- Add the conversion shares, remove the preferred from the EV bridge.\n- Otherwise keep it as preferred at liquidation value.");
C(T,2,"In an M&A deal, which share price do you use for the treasury stock method?","The offer price.\n- Options are cashed out at the deal price, so dilution depends on it.\n- That makes equity value and share count circular, solved by iteration.");
C(T,3,"EV = $100M, debt $20M, cash $10M, 45M shares. What is the share price?","$2.00.\n- Equity value = 100 - 20 + 10 = 90.\n- 90 / 45 = 2.");
C(T,2,"EBITDA $400M at 6x, $600M debt, $200M cash. EV and equity value? If equity value doubles, what is EV?","EV $2,400M, equity value $2,000M. After doubling, EV $4,400M.\n- Net debt is 400 and stays fixed.\n- 4,000 + 400 = 4,400.");
C(T,2,"$130M market cap, $40M debt, $20M cash, $5M NCI, $20M EBITDA. What is EV/EBITDA?","7.75x.\n- EV = 130 + 40 - 20 + 5 = 155.\n- 155 / 20 = 7.75.");
C(T,3,"Net debt is 3x EBITDA, EV/EBITDA is 10x, market cap is $560. What is EV?","$800.\n- EV = market cap + net debt, so 10x = market cap + 3x.\n- Market cap = 7x EBITDA, so EBITDA = 80.\n- EV = 10 x 80 = 800.");
C(T,3,"Net income $100, EBITDA $350, P/E 8x, EV/EBITDA 4x. What is net debt?","$600.\n- Equity value = 8 x 100 = 800.\n- EV = 4 x 350 = 1,400.\n- Net debt = 1,400 - 800.");
C(T,3,"P/E 20x, EV/EBITDA 7x, D&A 30, interest 30 at a 10% rate, equity value 400, no cash. What is the tax rate?","50%.\n- Net income = 400 / 20 = 20; debt = 30 / 10% = 300.\n- EV = 700, so EBITDA = 100, EBIT = 70, EBT = 40.\n- Tax = 40 - 20 = 20, which is 50%.");
C(T,2,"EV is 3x revenue and 8x EBITDA. What is the EBITDA margin?","37.5%.\n- Margin = (EV/Revenue) / (EV/EBITDA) = 3 / 8.");
C(T,3,"EV/EBITDA goes from 5x to 6x while EV/Revenue goes from 2x to 1x. What happened to margin?","It fell from 40% to about 17%.\n- Margin = EV/Rev / EV/EBITDA.\n- 2/5 = 40% before, 1/6 = 16.7% after.");
C(T,2,"EBITDA $120M, comps at 8x, cash $50M, debt $100M, NCI $20M. What is implied equity value?","$890M.\n- EV = 8 x 120 = 960.\n- 960 - 100 + 50 - 20 = 890.");
C(T,2,"You pay $1.5B for 60% of a company with $400M revenue, $200M EBITDA, $175M cash and $75M debt. What are EV/EBITDA and EV/Revenue?","12x EBITDA and 6x revenue.\n- 100% equity value = 1.5 / 0.6 = 2.5B.\n- EV = 2,500 + 75 - 175 = 2,400.");
C(T,3,"How do operating leases affect EV and EV/EBITDA?","Stay consistent.\n- If rent is inside EBITDA, do not add lease liabilities to EV.\n- If you add lease liabilities, use EBITDAR (rent added back).");
C(T,2,"A cash-rich company has positive EBITDA but negative EV. What does the market think?","That the operations will destroy value or that the cash will be burned.\n- Common in biotechs with failed trials or companies with large expected losses.");
C(T,2,"A company buys back stock. Does EV/EBITDA change? Does P/E?","EV/EBITDA is unchanged. P/E can change.\n- EV and EBITDA do not move.\n- EPS rises if the earnings yield beats the after-tax cost of cash, so P/E may shift.");

})();

// ---- healthcare.js
;(function(){
var T="Healthcare";
C(T,2,"How does a clinical-stage biotech's income statement differ from a normal company's?","Little or no revenue, R&D is the biggest cost, and it loses money.\n- Revenue, if any, is partner upfronts or milestones.\n- R&D then G&A dominate; no meaningful COGS.\n- Losses are funded by equity raises, so cash runway matters most.");
C(T,2,"Over the next five years, what does revenue look like for a Phase II oncology biotech? How could it be negative?","Mostly zero, apart from partner payments.\n- Upfronts and milestones from licensing.\n- Negative only through accounting reversals, like refunds or reversed collaboration revenue.");
C(T,3,"Seven years out at launch, what does the biotech P&L look like?","Product revenue arrives, COGS appears, SG&A jumps.\n- Launch SG&A can exceed revenue at first.\n- R&D shrinks relative to revenue.\n- Royalties owed to licensors may appear.");
C(T,3,"How do you forecast revenue for a pre-revenue biotech with one drug?","Peak sales model, risk-adjusted.\n- Patients x eligible share x market share x net price x compliance.\n- Ramp to peak over several years, then decline after loss of exclusivity.\n- Multiply by probability of success.");
C(T,3,"What are probability-weighted cash flows, and what PoS would you use for a Phase II oncology asset?","Each cash flow times the chance you get to it. About 10 to 15% from Phase II to approval.\n- Roughly 25 to 30% pass Phase II, about half pass Phase III, about 90% of filings are approved.\n- Oncology is below average.");
C(T,3,"How do you risk-adjust biotech costs down to EBIT?","Only weight costs that depend on success.\n- Current-phase R&D: 100%, it is committed.\n- Later trials: weighted by the chance of reaching them.\n- COGS and launch SG&A: weighted like revenue.");
C(T,3,"You are in Phase II. Would you risk-adjust Phase II R&D at 20%?","No.\n- Current-phase spend happens regardless, so take it at 100%.\n- Risk-adjusting it understates burn and overstates value.");
C(T,3,"If you built COGS bottom-up, how would you risk-adjust it?","Same probability as revenue.\n- COGS only exists if the drug is approved and sold.\n- Pre-launch inventory builds use the lower, earlier-stage probability.");
C(T,3,"In a biotech's WACC, does equity or debt matter more?","Equity.\n- Most biotechs have little or no debt.\n- WACC is basically the cost of equity.");
C(T,3,"How do you handle terminal value for a single-asset biotech?","Usually none, or a declining tail.\n- Model through loss of exclusivity.\n- After LOE, revenue erodes toward zero, so perpetual growth makes no sense.");
C(T,3,"Why project a biotech DCF's cash flows down to zero?","Patents expire.\n- Generics or biosimilars erode the product's revenue.\n- Unless there is a pipeline, value ends with the product.");
C(T,3,"For a single-asset Phase II biotech, how far out would you model?","To the end of patent life, often 15 to 20 years.\n- Long enough to capture launch, peak sales and the post-LOE decline.");
C(T,3,"After loss of exclusivity, what decides how steep the revenue drop is?","How easy the drug is to copy.\n- Small molecule versus biologic.\n- Number of entrants, patent thickets, payer generic mandates, specialty versus primary care.");
C(T,3,"How does molecule complexity affect generic or biosimilar entry?","More complex means slower, shallower erosion.\n- Small molecules can lose 80 to 90% within a year.\n- Biologics need biosimilars, which are costly to develop and slower to take share.");
C(T,2,"Walk me through the clinical phases and their rough success rates.","Phase I safety, Phase II efficacy signal, Phase III confirmation, then filing.\n- Roughly 50% pass Phase I, 30% Phase II, 55 to 60% Phase III, 90% of filings approved.\n- About 8 to 10% from Phase I to approval overall; lower in oncology.");
C(T,3,"Which multiples work for pre-revenue biotechs? Would you LBO one?","No standard multiples, and no LBO.\n- Use EV versus cash, EV per asset by stage, EV / risk-adjusted peak sales.\n- No cash flow to service debt.");
C(T,3,"Roughly what share of value comes from terminal value in a biotech DCF?","Small or none.\n- Value comes from peak sales years inside the forecast.");
C(T,3,"Book equity $1,000, market cap $2,000, sales $500, EBITDA $200, debt and cash $300 each, cash flow $100, WACC 10%, growth 5%. Fairly valued?","Roughly fair, slightly cheap.\n- P/B 2x, EV/EBITDA 10x, EV/Sales 4x.\n- Gordon value of cash flow: 100 x 1.05 / 5% = 2,100, near the 2,000 market cap.");
C(T,3,"What matters when a large biotech buys a small one?","Asset value, price and keeping the science.\n- Pipeline and probability of success.\n- Premium versus rNPV; structure (cash, stock, CVR).\n- Antitrust, retaining key scientists, the buyer's patent cliff.");
C(T,3,"A client says you are undervaluing their biotech. Which levers do you check?","The big assumptions.\n- Peak sales: patients, share, price.\n- PoS and launch timing.\n- LOE date, COGS, SG&A, discount rate.");
C(T,3,"What is a realistic timeline for a drug to reach market?","About 10 to 12 years from first-in-human to approval.\n- Roughly 6 to 8 years from starting Phase II.");
C(T,3,"Are biotech M&A premiums higher or lower than other sectors? Why?","Higher, often 50 to 100%.\n- Value is concentrated in a few assets.\n- The market prices in failure risk; a buyer pays for control and upside.");
C(T,3,"Which CAPM inputs matter most for biopharma?","Beta and any size or specific risk premium.\n- Many banks use a 10 to 15% discount rate and risk-adjust cash flows separately.\n- Avoid counting risk twice.");
C(T,3,"$1B EV, 50% Phase III success probability, $100 debt, $200 cash. What is equity value if the trial succeeds?","About $2.1B.\n- Today's $1B reflects a 50% chance, so success roughly doubles EV to $2B (if failure is worth about zero).\n- Equity = 2,000 - 100 + 200.");
C(T,3,"How can a biotech raise money without diluting shareholders?","Partner, borrow or sell rights.\n- Licensing upfronts and milestones, regional out-licenses.\n- Royalty monetization, venture debt.\n- Grants or selling a priority review voucher.");
C(T,3,"What drives the price of a drug?","Value delivered versus alternatives.\n- Clinical benefit and unmet need, patient population size.\n- Comparator pricing, payer pushback, orphan status, policy.");
C(T,3,"A patent expires in 5 years. How do you handle terminal value?","Run cash flows through expiry, model the erosion curve, and use little or no terminal value.");
C(T,3,"How would you value a biotech with a DCF?","Sum-of-the-parts rNPV.\n- For each asset: peak sales, margins, timing, LOE, times cumulative PoS.\n- Discount, subtract unallocated R&D and G&A, add cash.");
C(T,3,"What are the key differences between a biotech DCF and a normal DCF?","Risk-adjusted cash flows, finite asset life, asset-by-asset.\n- Cash flows weighted by PoS.\n- Ends at LOE instead of a terminal value.\n- Funding needs and dilution matter.");
C(T,3,"Why would big pharma buy a biotech despite low success rates?","Patent cliffs.\n- It needs to replace lost revenue.\n- Buying de-risked, late-stage assets can beat internal R&D odds.\n- Big pharma's salesforce can launch faster.");
C(T,3,"Why might two biotechs merge, and why might a small biotech resist a sale?","Merge for cash, pipeline and cost savings. Resist when data could raise value.\n- Management may think a readout will re-rate the stock.\n- The premium may look too low.");
C(T,3,"Why would a biotech do internal R&D instead of acquiring?","Cost versus speed.\n- R&D builds owned assets but is slow and fails often.\n- Acquisitions buy de-risked assets at a premium.");
C(T,3,"What capital would a pre-revenue biotech most likely raise?","Equity.\n- Follow-ons, PIPEs, venture rounds.\n- Plus partnership upfronts. Debt is hard without cash flow.");
C(T,3,"A public biotech raises $100M in a follow-on. What changes in the statements?","Cash +100, equity +100, financing inflow +100.\n- No income statement impact.\n- Share count rises, diluting existing holders.");
C(T,3,"Where do you apply probability of success in a biotech DCF, and what are the pitfalls?","On cash flows that need success.\n- Revenue, COGS, launch SG&A, later trials.\n- Pitfalls: a flat PoS for every year, double counting risk in the discount rate, not risk-adjusting costs.");
C(T,3,"Why is it wrong to risk-adjust revenue but not costs?","Success-dependent costs disappear if the drug fails.\n- Leaving them at 100% understates value.");
C(T,2,"What exclusivity periods protect a new drug in the US?","Patents plus regulatory exclusivity.\n- Patent: 20 years from filing, often 10 to 12 left at launch.\n- New chemical entity: 5 years. Biologics: 12 years. Orphan: 7 years.");
C(T,3,"What does the Inflation Reduction Act mean for drug valuation?","Medicare can negotiate prices for top-spend drugs.\n- As enacted: about 9 years after approval for small molecules, 13 for biologics.\n- Shortens the effective peak period, especially for small molecules. (Check current rules before interviews.)");
C(T,2,"What is gross-to-net?","The gap between list price and what the maker actually keeps.\n- Rebates to PBMs and payers, Medicaid and 340B discounts, chargebacks, copay support.");
C(T,2,"What do PBMs do?","Manage drug benefits for insurers and employers.\n- Build formularies, negotiate rebates, run pharmacy networks.\n- Formulary position drives a drug's volume.");
C(T,2,"What is a biosimilar, and why is erosion slower than for generics?","A near-copy of a biologic.\n- Costly to develop and manufacture.\n- Needs comparability data; physicians and payers switch more slowly.");
C(T,3,"What is royalty financing?","Selling part of future royalty streams for cash today.\n- Non-dilutive capital.\n- The company gives up some upside.");
C(T,3,"How do you value a CVR in a biotech deal?","Probability x payout, discounted.\n- Estimate the chance of each milestone and its timing.\n- Discount at a rate that fits the risk and the buyer's credit.");
C(T,3,"How is a medtech company valued differently from a biotech?","Revenue-based multiples and normal DCFs.\n- Shorter, cheaper approval paths for many devices.\n- Recurring disposables and installed base matter.");
C(T,2,"What metrics matter for healthcare services companies?","Volume, rate and labor.\n- Patient visits or admissions, revenue per visit, payer mix.\n- Labor cost as a share of revenue; often valued on EV/EBITDA.");
C(T,2,"What is the medical loss ratio for an insurer?","Medical claims / premiums.\n- Higher MLR means thinner margins.\n- The ACA sets minimums: 80% individual and small group, 85% large group.");
C(T,2,"Why do life science tools companies trade at premium multiples?","Recurring revenue.\n- Razor-razorblade model: instruments plus consumables.\n- Exposure to all of biopharma R&D rather than one drug.");
C(T,3,"What is rNPV in one sentence, and how do you build it?","NPV where each year's cash flow is multiplied by its probability of happening.\n- Build the unrisked forecast, apply cumulative PoS by phase, then discount.");
C(T,3,"First-in-class versus best-in-class: how does it affect your model?","Timing versus share.\n- First-in-class: earlier launch, but share may be taken later.\n- Best-in-class: later launch, can win share with better data or convenience.");
C(T,3,"What drives how many sales reps you can cut in a pharma merger?","Overlap.\n- Overlapping prescribers and therapeutic areas.\n- Launches that still need coverage, and contract terms.");
C(T,3,"If an associate disagrees with your LOE assumption, how do you align before presenting?","Get to the evidence.\n- Walk through patent dates, exclusivity, litigation and analog erosion curves.\n- Show the sensitivity, agree a base case, flag the alternative.");

})();

// ---- lbo.js
;(function(){
var T="LBO";
C(T,1,"Walk me through an LBO.","Buy with mostly debt, pay it down with the company's cash, sell later.\n- Set purchase price and sources and uses.\n- Project cash flow and use it to repay debt.\n- Exit around year 5; equity = exit EV - remaining debt; compute IRR and MOIC.");
C(T,1,"What are the key inputs in an LBO?","Entry, financing, operations, exit.\n- Purchase multiple and leverage.\n- Debt terms and cash flow for paydown.\n- Exit year and exit multiple.");
C(T,2,"Why do sponsors use leverage?","To magnify equity returns.\n- Debt is cheaper than equity and tax deductible.\n- The same gain on a smaller equity check means a higher return.");
C(T,2,"How do you boost returns in an LBO?","Buy cheap, grow, pay down debt, sell high.\n- Lower entry multiple, more leverage.\n- EBITDA growth and multiple expansion.\n- Faster debt paydown or an earlier exit.");
C(T,2,"What makes a good LBO candidate?","Steady cash to service debt.\n- Stable, recurring revenue and strong market position.\n- Low capex needs and room to improve margins.\n- Clear exit path.");
C(T,2,"What macro factors drive LBO returns?","Rates, credit and multiples.\n- Cost and availability of debt.\n- Valuation levels at entry and exit.\n- Economic growth driving EBITDA.");
C(T,3,"An extra $1 of EBITDA or an extra $1 of debt paydown: which is worth more?","EBITDA.\n- It is capitalized at the exit multiple, so worth roughly $8 to $10 of EV.\n- It also generates cash. Debt paydown is worth $1.");
C(T,2,"Which assumption usually moves LBO returns the most?","Exit multiple, then EBITDA growth.\n- A 1x change on a large EBITDA base swings equity value a lot.");
C(T,3,"Can you get a 15% IRR selling at the same price you paid?","Yes.\n- Free cash flow pays down debt, so equity value grows even with flat EV.\n- Dividends along the way also help.");
C(T,3,"You buy and sell a company for $100. How can you still make money, apart from a dividend recap?","Debt paydown.\n- With leverage, cash flow repays debt, so your equity slice of the same $100 grows.\n- Without leverage or cash build, you cannot.");
C(T,3,"A PE firm buys a company for $100M and sells for $300M after 5 years. MOIC and IRR?","3.0x and about 25%.\n- 3^(1/5) - 1 = 24.6%.");
C(T,3,"$100M EBITDA bought at 2.5x with 2/3 loan-to-value. Half the debt is repaid in a year, exit at the same value. MOIC?","About 2.0x.\n- EV 250, debt 167, equity 83.\n- Debt falls to 83; exit equity = 250 - 83 = 167.");
C(T,3,"Entry: $150M EBITDA at 9x with 5x leverage. Exit: $240M EBITDA at 9.5x with 3x leverage after 5 years. Returns?","About 2.6x and 21%.\n- Equity in: 1,350 - 750 = 600.\n- Equity out: 2,280 - 720 = 1,560.\n- Most of the gain comes from EBITDA growth.");
C(T,3,"Buy at 9x and exit at 9x after 5 years. 4x leverage, half repaid. How much EBITDA growth for a 25% IRR?","About 90%.\n- Equity in 5x; target MOIC 1.25^5 = 3.05x, so 15.3x out.\n- Exit EV = 15.3 + 2 debt = 17.3x of entry EBITDA.\n- 17.3 / 9 = 1.92x EBITDA.");
C(T,4,"Buy at 10x with 3x leverage. EBITDA grows $10M a year, exit at 15x after 5 years, 5% of principal repaid each year. What entry EBITDA gives a 20% IRR?","About $160M (your recorded answer).\n- Equity in = 7E; target equity out = 7E x 1.2^5 = 17.4E.\n- Exit EV = 15(E + 50); debt left = 3E x 0.75 = 2.25E.\n- Solve 15E + 750 - 2.25E = 17.4E.");
C(T,3,"$30M EBITDA, 10x purchase multiple, $100M of debt. What is the equity check?","$200M before fees.\n- EV 300 - debt 100.");
C(T,3,"How is an LBO IRR different from a DCF?","LBO IRR is a levered equity return at a set price; a DCF gives value at a set return.\n- LBO solves for return given price.\n- DCF solves for price given required return.");
C(T,3,"How much debt can an LBO support, and in what tranches?","Set by what lenders accept on leverage and coverage.\n- Typically 4 to 6x EBITDA depending on sector and market.\n- Revolver, term loans, then second lien, notes, mezz in order of seniority.");
C(T,2,"What happens to the old shareholders in an LBO?","They are bought out for cash.\n- New sponsor equity and any management rollover replace them.\n- Existing debt is usually refinanced.");
C(T,3,"How do asset write-ups affect LBO returns?","Only if they are tax deductible.\n- Stock deal: book-only write-up, no cash effect.\n- Asset deal or 338(h)(10): bigger tax deductions, more cash for paydown, higher IRR.");
C(T,3,"In what order do you repay LBO debt with excess cash?","Cheapest to prepay and most senior first.\n- Revolver, then term loan A, then term loan B.\n- Bonds usually have call protection, so they come last.");
C(T,3,"What if the company cannot cover a mandatory debt payment?","Draw the revolver.\n- In the model, the revolver plugs any cash shortfall and is repaid first.");
C(T,3,"Why keep a minimum cash balance in an LBO model?","Day-to-day liquidity.\n- Seasonality, working capital swings and a buffer against covenants.");
C(T,3,"How does an LBO capture the time value of money?","Through IRR.\n- Same MOIC over a longer hold means a lower IRR.");
C(T,3,"How do interest tax shields help an LBO?","More cash for debt paydown.\n- Interest cuts taxable income, so less cash goes to tax.");
C(T,3,"EBITDA drops sharply after the buyout. What happens?","Leverage spikes and equity takes the hit.\n- Covenants may trip and cash sweep slows.\n- Options: amendment, equity cure, or restructuring.");
C(T,3,"Maintenance versus incurrence covenants: what is the difference?","When they are tested.\n- Maintenance: every quarter, no matter what.\n- Incurrence: only when the company takes an action like new debt or dividends.\n- Term loan B and bonds are usually covenant-lite.");
C(T,3,"Why would a mezzanine lender accept warrants?","For upside to compensate for being junior.\n- Lets the coupon be lower, which eases cash interest.");
C(T,2,"What is PIK interest and why use it?","Interest added to principal instead of paid in cash.\n- Saves cash early on.\n- But it compounds, so the debt balance grows.");
C(T,3,"How does PIK debt change LBO returns?","More cash early, more debt at exit.\n- Exit equity is lower because the balance has grown.\n- Can still lift IRR if it allows more leverage.");
C(T,2,"What is the impact of a dividend recap on IRR and MOIC?","IRR up, MOIC flat to slightly down.\n- Cash comes back earlier.\n- Extra interest cost lowers final exit equity a bit.");
C(T,2,"What are stapled financing and NAV loans?","Two sponsor financing tools.\n- Stapled: a debt package pre-arranged by the sell-side bank for any bidder.\n- NAV loan: borrowing against a fund's portfolio value.");
C(T,3,"Why is an LBO analysis often seen as a floor valuation?","It shows what a financial buyer can pay and still hit its return.\n- Strategics with synergies can usually pay more.");
C(T,3,"Would you LBO a biotech?","Generally no.\n- No stable cash flow to service debt.\n- Binary clinical risk.\n- Exception: royalty or commercial-stage businesses with steady cash.");
C(T,2,"What is a sources and uses table in an LBO?","Sources: debt tranches, sponsor equity, rollover.\n- Uses: purchase equity, refinanced debt, fees.\n- Both sides must balance.");
C(T,2,"What are typical sponsor return targets?","About 20 to 25% IRR and 2.5 to 3x MOIC over 3 to 5 years.\n- Lower in competitive markets or for safer assets.");
C(T,2,"What is a cash sweep?","Excess cash goes to repaying debt.\n- Often required by term loans as a percentage of excess cash flow.");
C(T,2,"What is unitranche debt?","One loan blending senior and junior debt at one rate.\n- Common from private credit lenders; simpler and faster.");
C(T,2,"What is a buy-and-build strategy?","Buy a platform, then bolt on smaller acquisitions.\n- Small deals cost lower multiples.\n- The combined company exits at a higher multiple: multiple arbitrage.");
C(T,2,"Why do sponsors want management to roll equity?","Alignment.\n- Management keeps skin in the game.\n- Also reduces the sponsor's equity check.");
C(T,2,"What are the exit options for a sponsor?","Sell to a strategic, sell to another sponsor, or IPO.\n- Dividend recaps return cash without exiting.");
C(T,3,"How do you break down where LBO returns came from?","Three buckets.\n- EBITDA growth x entry multiple.\n- Multiple change x exit EBITDA.\n- Net debt paydown.");
C(T,2,"Walk me through a paper LBO.","Simplify everything and do it by hand.\n- Entry EV and equity from multiple and leverage.\n- Grow EBITDA, sum free cash flow to pay down debt.\n- Exit EV minus debt left; MOIC and approximate IRR.");
C(T,3,"Would you rather lend to a growing company or one with stable cash flow?","As a lender, stable cash flow.\n- Your upside is capped at the coupon; your risk is default.");
C(T,3,"What makes an LBO of a private company harder?","Less information and fewer comps.\n- Unaudited financials, key-person risk.\n- Smaller size can make financing harder.");
C(T,3,"How do management options affect sponsor returns?","They dilute the sponsor at exit.\n- Sponsor IRR falls slightly, but incentives improve.");
C(T,3,"How would you cut net debt / EBITDA right away without issuing equity?","Sell assets and repay debt, or use excess cash to repay debt.\n- Cost cuts raise EBITDA, but more slowly.");
C(T,3,"Strategic or financial buyer: who values a company higher and why?","Usually the strategic.\n- It can count synergies.\n- A sponsor is limited by leverage and its target IRR.");

})();

// ---- ma.js
;(function(){
var T="M&A";
C(T,1,"What does accretive or dilutive mean?","Whether the buyer's EPS goes up or down after the deal.\n- Accretive: pro forma EPS above standalone EPS.\n- A quick first test, not proof the deal creates value.");
C(T,2,"Company A ($30 stock, $3 EPS) buys Company B ($10 stock, $1 EPS) for all cash. Accretive or dilutive?","Accretive, before any premium.\n- B's earnings yield is 1 / 10 = 10%.\n- After-tax cost of cash is only a few percent.\n- Buying a 10% yield with cheaper money adds EPS.");
C(T,2,"What could make an all-cash deal dilutive?","Anything that pushes the cost above the target's earnings yield.\n- A big premium.\n- Expensive financing or fees.\n- New D&A from write-ups, integration costs.");
C(T,2,"What is the quick rule for an all-stock deal?","Compare P/E ratios.\n- Buyer P/E above the price-paid P/E: accretive.\n- Below: dilutive.\n- Ignores synergies and write-ups.");
C(T,2,"A 25x P/E company buys a 15x P/E company with all stock. Accretive or dilutive?","Accretive.\n- It pays with expensive paper (25x) for cheaper earnings (15x).");
C(T,2,"An 8x P/E company buys a 12x P/E company with all stock. Accretive or dilutive?","Dilutive.\n- It issues too many cheap shares per dollar of earnings acquired.");
C(T,3,"A 10x P/E buyer acquires a 12x P/E target in stock. Is it automatically dilutive?","Before synergies, yes; with enough synergies, no.\n- Synergies raise pro forma earnings.\n- Check the price paid, not just the pre-deal P/E.");
C(T,3,"A 10x P/E company buys a 5x P/E company. All stock, then all debt?","Accretive both ways.\n- Stock: pays 10x paper for 5x earnings.\n- Debt: target earnings yield is 20%, far above the after-tax cost of debt.");
C(T,3,"P/E ratios suggest a stock deal is neutral. What does that mean?","Buyer P/E equals the price-paid P/E.\n- Any synergy tips it accretive; any extra cost tips it dilutive.");
C(T,3,"A: 10 shares at $25, NI $10. It buys B (NI $10) for $150 in stock. Accretive?","Accretive: EPS goes from $1.00 to $1.25.\n- New shares = 150 / 25 = 6.\n- Pro forma NI 20 on 16 shares.");
C(T,3,"A: P/E 5x. B: P/E 8x. Paid 50% stock, 25% debt at 5%, 25% cash at 2%. Tax 50%. Accretive?","Accretive.\n- Costs: stock 20% (1/5), debt 2.5%, cash 1%.\n- Weighted: 10% + 0.6% + 0.25% = 10.9%.\n- Below B's 12.5% earnings yield.");
C(T,3,"A buyer borrows at 10% (tax 25%) to buy a target at 20x P/E. Accretive?","Dilutive.\n- Target earnings yield = 5%.\n- After-tax cost of debt = 7.5%.\n- Paying 7.5% for a 5% yield loses EPS.");
C(T,3,"Pro forma EPS is $1.30 versus $1.40 standalone. Tax 20%. What pretax synergies per share break even?","12.5 cents per share.\n- Need 10 cents after tax.\n- 0.10 / (1 - 0.20) = 0.125.");
C(T,3,"How do you calculate break-even synergies?","EPS gap x pro forma shares, grossed up for tax.\n- (Standalone EPS - pro forma EPS) x pro forma shares / (1 - t).");
C(T,2,"$1 of cost synergies or $1 of revenue synergies: which is worth more?","Cost synergies.\n- More certain and faster to achieve.\n- They fall straight to profit; revenue synergies only add their margin.");
C(T,2,"What are the building blocks of a merger model?","Projections, price, funding, accounting, combination.\n- Standalone forecasts and purchase price.\n- Sources and uses, purchase price allocation.\n- Synergies, pro forma IS, EPS accretion, credit stats.");
C(T,2,"Why would a company do a dilutive deal?","Long-term strategy beats near-term EPS.\n- Access to growth, technology or markets.\n- Large synergies that take time to land.");
C(T,2,"What makes a good acquisition?","Price below standalone value plus achievable synergies.\n- Clear strategic fit.\n- Manageable financing and integration.\n- Returns above the cost of capital.");
C(T,2,"Compare cash, stock and debt as deal consideration.","Cash is certain, stock shares risk, debt is cheap but levers up.\n- Cash: simple, uses balance sheet capacity.\n- Stock: no cash out, but dilutes and seller shares upside and risk.\n- Debt: tax-deductible, adds leverage.");
C(T,2,"Besides accretion, why might a buyer pay in stock?","Preserve cash and credit rating.\n- Share integration risk with the seller.\n- Use richly valued stock as cheap currency.");
C(T,3,"How does the choice of cash versus stock relate to synergies?","It decides who shares the synergies.\n- Cash: buyer keeps all synergy upside and risk.\n- Stock: seller shares in both.\n- Uncertain synergies push buyers toward stock or earn-outs.");
C(T,2,"Why would a target's shareholders prefer stock?","Upside and tax deferral.\n- They share in synergies and future growth.\n- Stock deals can be tax-free reorganizations.");
C(T,2,"What is a sources and uses table?","Where the money comes from and where it goes.\n- Sources: cash, new debt, new equity.\n- Uses: purchase equity, refinance debt, fees. Both sides must match.");
C(T,3,"Walk me through purchase price allocation.","Allocate the price to the target's assets at fair value.\n- Write up tangible and intangible assets.\n- Create a DTL on the write-ups.\n- The rest is goodwill.");
C(T,3,"Asset deal versus stock deal: who prefers which?","Buyers prefer asset deals; sellers prefer stock deals.\n- Asset deal: buyer gets a tax step-up and can leave liabilities behind.\n- Stock deal: seller avoids double tax and passes on all liabilities.");
C(T,2,"What is a Section 338(h)(10) election?","A stock purchase treated as an asset purchase for tax.\n- Buyer gets a stepped-up tax basis and bigger deductions.\n- Needs an S corp or a subsidiary of a consolidated group, and a joint election.");
C(T,2,"What is an earn-out or CVR and why use it?","Extra payment if future targets are hit.\n- Bridges a valuation gap between buyer and seller.\n- Shifts risk on uncertain outcomes, like FDA approval.");
C(T,3,"Fixed versus floating exchange ratio: what is the difference?","Fixed: set number of shares, so value moves with the buyer's stock. Floating: set value, so share count moves.\n- Collars cap how far either can move.");
C(T,2,"Why use a tender offer instead of a merger vote?","Speed.\n- Can close in about a month instead of waiting for a shareholder meeting.");
C(T,2,"What is a break fee and a reverse termination fee?","Compensation if the deal falls apart.\n- Break fee: target pays if it walks for a better offer.\n- Reverse fee: buyer pays if it walks, often for antitrust or financing failure.");
C(T,2,"What are no-shop and go-shop clauses?","Rules on seeking other bidders after signing.\n- No-shop: target cannot solicit offers.\n- Go-shop: target can shop the deal for a set window.");
C(T,2,"What is a MAC clause?","Material adverse change.\n- Lets the buyer walk if the target's business deteriorates badly before closing.\n- Rarely successfully invoked.");
C(T,2,"What is a fairness opinion?","A bank's view that the price is fair from a financial point of view.\n- Supports the board's decision; not a recommendation to vote.");
C(T,2,"What is contribution analysis?","Compare what each side contributes to what each side owns.\n- Revenue, EBITDA, net income share versus pro forma ownership.\n- Common in mergers of equals.");
C(T,3,"Why is EPS accretion a flawed test of a deal?","It ignores the cost of equity and risk.\n- Cheap debt makes almost anything accretive.\n- Value creation needs returns above the cost of capital.");
C(T,2,"Spin-off, carve-out and split-off: what is the difference?","Ways to separate a business.\n- Spin-off: shares distributed to existing holders.\n- Carve-out: IPO of part of the subsidiary.\n- Split-off: holders swap parent shares for subsidiary shares.");
C(T,2,"What is a poison pill?","A takeover defense.\n- Lets other holders buy cheap shares if a raider crosses a stake threshold.\n- Makes a hostile bid very dilutive to the raider.");
C(T,2,"Walk me through a sell-side M&A process.","Prepare, market, bid, sign.\n- Teaser and NDA, then the CIM.\n- First-round IOIs, management presentations, data room.\n- Final bids, negotiation, signing, closing.");
C(T,2,"How do strategic and financial buyers differ?","Strategics pay for synergies; sponsors pay for returns.\n- Strategics can usually pay more.\n- Sponsors are capped by leverage and target IRR.");
C(T,3,"How do you calculate pro forma ownership in a stock deal?","New shares issued / (existing buyer shares + new shares).\n- New shares = purchase equity value / buyer share price.");
C(T,3,"What happens to EPS when a company borrows to buy back shares?","Rises if the earnings yield beats the after-tax cost of debt.\n- High-P/E stocks have low earnings yields, so it can be dilutive.");
C(T,3,"A company has EPS of $7 and a 15x P/E. The tax rate falls from 30% to 15%. New price?","$127.50, holding P/E flat.\n- Pretax EPS = 7 / 0.7 = 10.\n- New EPS = 10 x 0.85 = 8.50; x 15 = 127.50.");
C(T,3,"What is debt pushdown?","Moving acquisition debt down to the target.\n- Interest is then deducted against the target's own taxable income.");
C(T,3,"How do you treat the target's convertible debt in an acquisition?","Depends on the offer price.\n- In the money: treat as converted shares, cashed out at the offer.\n- Out of the money: stays debt, often repaid on change of control.");
C(T,3,"The buyer has a much lower tax rate than the target. Why does that matter?","The target's profits get taxed at the lower rate.\n- Raises pro forma earnings and makes the deal more accretive.");
C(T,3,"How can a merger model help in negotiations?","It sets the buyer's walk-away price.\n- Shows the price where accretion or returns break even.\n- Shows how much synergy value there is to share.");
C(T,2,"What is HSR and why does it matter?","US antitrust pre-merger filing.\n- Deals above a size threshold must wait for review.\n- A second request can delay closing for months.");

})();

// ---- mental.js
;(function(){
// Mental: quick, conceptual, easy numbers. Designed for doing in your head.
var T="Mental";
C(T,1,"WACC goes up. What happens to DCF value?","Down.\n- Every future cash flow is discounted more.");
C(T,1,"Terminal growth goes up. What happens to DCF value?","Up.\n- The terminal value denominator (WACC - g) shrinks.");
C(T,1,"Tax rate goes up. What happens to unlevered free cash flow?","Down.\n- NOPAT falls because more of EBIT goes to tax.");
C(T,1,"Beta goes up. What happens to cost of equity?","Up.\n- Ke = rf + beta x ERP.");
C(T,1,"Risk-free rate goes up. What happens to cost of equity and DCF value?","Cost of equity up, value down.");
C(T,1,"A company adds a moderate amount of debt. What usually happens to WACC?","Down.\n- Debt is cheaper than equity and tax deductible.\n- Until distress costs kick in.");
C(T,1,"Exit multiple goes up by 1x in an LBO. IRR?","Up.\n- Bigger exit EV, same debt, more equity.");
C(T,1,"Same MOIC, but you hold for 7 years instead of 5. IRR?","Lower.\n- The same gain spread over more years.");
C(T,1,"More leverage in an LBO, everything else equal. IRR?","Higher.\n- Smaller equity check for the same gain, if the business performs.");
C(T,1,"Depreciation goes up by $10. Tax 25%. What happens to cash?","Up $2.50.\n- The tax shield on 10.");
C(T,1,"Accounts receivable go up. Cash flow?","Down.\n- Sales booked, cash not collected.");
C(T,1,"Accounts payable go up. Cash flow?","Up.\n- You are paying suppliers later.");
C(T,1,"Inventory goes up. Cash flow?","Down.\n- Cash is tied up in stock.");
C(T,1,"Deferred revenue goes up. Cash flow?","Up.\n- Customers paid in advance.");
C(T,1,"A company issues stock. Does EV change?","No.\n- Equity value up, cash up by the same amount.");
C(T,1,"A company pays a dividend. Does EV change?","No.\n- Equity value and cash both fall.");
C(T,1,"A company buys back stock with cash. Net debt?","Up.\n- Cash went out.");
C(T,1,"A company repays debt with cash. Net debt?","Unchanged.\n- Debt and cash fall together.");
C(T,1,"A 20x P/E company buys a 10x P/E company with stock. Accretive?","Accretive.\n- Expensive paper buys cheap earnings.");
C(T,1,"A 10x P/E company buys a 20x P/E company with stock. Accretive?","Dilutive.\n- Cheap paper buys expensive earnings.");
C(T,1,"Target P/E is 10x. After-tax cost of debt is 4%. Debt-funded deal accretive?","Accretive.\n- 10% earnings yield beats a 4% cost.");
C(T,1,"Target P/E is 25x. After-tax cost of debt is 6%. Debt-funded deal accretive?","Dilutive.\n- 4% earnings yield is below a 6% cost.");
C(T,1,"What is the earnings yield of a 20x P/E stock?","5%.\n- 1 / 20.");
C(T,1,"What is the earnings yield of an 8x P/E stock?","12.5%.\n- 1 / 8.");
C(T,1,"How long does money take to double at 8%?","About 9 years.\n- Rule of 72: 72 / 8.");
C(T,1,"How long does money take to double at 12%?","About 6 years.\n- 72 / 12.");
C(T,1,"2x in 5 years is roughly what IRR?","About 15%.");
C(T,1,"2x in 3 years is roughly what IRR?","About 26%.");
C(T,1,"3x in 5 years is roughly what IRR?","About 25%.");
C(T,1,"3x in 3 years is roughly what IRR?","About 44%.");
C(T,1,"2.5x in 5 years is roughly what IRR?","About 20%.");
C(T,1,"2x in 4 years is roughly what IRR?","About 19%.");
C(T,1,"2x in 7 years is roughly what IRR?","About 10%.");
C(T,1,"A 20% IRR for 5 years is roughly what MOIC?","About 2.5x.");
C(T,1,"A 25% IRR for 5 years is roughly what MOIC?","About 3x.");
C(T,1,"EV/Revenue 2x, EV/EBITDA 10x. EBITDA margin?","20%.\n- 2 / 10.");
C(T,1,"EV/Revenue 3x, EV/EBITDA 6x. EBITDA margin?","50%.\n- 3 / 6.");
C(T,1,"EV 1,000, debt 300, cash 100. Equity value?","800.\n- 1,000 - 300 + 100.");
C(T,1,"Equity value 500, debt 200, cash 50. EV?","650.\n- 500 + 200 - 50.");
C(T,1,"EBITDA 50 at 10x. Debt 200, no cash. Equity value?","300.\n- EV 500 - 200.");
C(T,1,"EPS $2, P/E 15x. Share price?","$30.");
C(T,1,"Price $40, EPS $4. P/E?","10x.");
C(T,1,"$10 of pretax interest, tax 25%. After-tax cost?","$7.50.");
C(T,1,"Pretax cost of debt 8%, tax 25%. After-tax?","6%.");
C(T,1,"rf 4%, beta 1, ERP 6%. Cost of equity?","10%.");
C(T,1,"rf 3%, beta 2, ERP 5%. Cost of equity?","13%.");
C(T,1,"50% debt at 4% after tax, 50% equity at 12%. WACC?","8%.");
C(T,1,"Next year FCF 10, WACC 10%, growth 0%. Value?","100.\n- 10 / 10%.");
C(T,1,"Next year FCF 10, WACC 10%, growth 5%. Value?","200.\n- 10 / 5%.");
C(T,1,"10 options at a $50 strike, stock at $100. Net new shares (TSM)?","5.\n- Proceeds 500 buy back 5 shares.");
C(T,1,"10 options at a $50 strike, stock at $40. Net new shares?","0.\n- Out of the money.");
C(T,1,"Buy at EV 100 with 60 debt. Exit at EV 120 with 40 debt. MOIC?","2.0x.\n- Equity 40 in, 80 out.");
C(T,1,"Buy at EV 100 with 50 debt. Exit at EV 100 with 0 debt. MOIC?","2.0x.\n- Equity 50 in, 100 out, all from paying down debt.");
C(T,1,"Which raises FCF more: $10 less capex or $10 less opex?","Capex.\n- Opex savings get taxed; capex savings do not.");
C(T,1,"Revenue grows 10% and the company has fixed costs. Does EBITDA grow more or less than 10%?","More.\n- Operating leverage.");
C(T,1,"Comps or precedents: which is usually higher?","Precedents.\n- They include a control premium.");
C(T,1,"Cost synergies or revenue synergies: which do buyers trust more?","Cost synergies.\n- More certain and in management's control.");
C(T,1,"Higher WACC: a utility or a biotech?","Biotech.\n- Much riskier cash flows.");
C(T,1,"Who gets paid first in bankruptcy: secured lenders or bondholders?","Secured lenders.");
C(T,1,"Rates rise. Bond prices?","Fall.");
C(T,1,"Which is more rate-sensitive: a 2-year or a 10-year bond?","The 10-year.\n- Longer duration.");
C(T,1,"A target is bought at a 30% premium to a $50 share price. Offer price?","$65.");
C(T,1,"Offer $60, unaffected price $48. Premium?","25%.\n- 12 / 48.");
C(T,1,"A drug has $1B peak sales and a 20% chance of approval. Risk-adjusted peak sales?","$200M.");
C(T,1,"Phase II to III is 30%, Phase III to approval 60%, filing 90%. Cumulative PoS from Phase II?","About 16%.\n- 0.3 x 0.6 x 0.9.");
C(T,1,"Net debt 300, EBITDA 100. Leverage?","3x.");
C(T,1,"EBITDA 100, interest 25. Interest coverage?","4x.");
C(T,1,"A company with no debt adds debt. Cost of equity?","Up.\n- More financial risk for shareholders.");
C(T,1,"Mid-year convention versus end-of-year: which gives a higher value?","Mid-year.\n- Cash flows are discounted for half a year less.");
C(T,1,"A company switches from leasing to owning its stores. What happens to EBITDA?","Up, for operating leases.\n- Rent leaves opex; depreciation and interest replace it below EBITDA.");

})();

// ---- saas.js
;(function(){
var T="Markets & SaaS";
C(T,2,"Why might ARR be below revenue, and why above?","Below: one-time fees in revenue or a shrinking base. Above: fast-growing subscriptions.\n- ARR is a current run rate; revenue lags it as contracts ramp.");
C(T,2,"What is the Rule of 40?","Growth rate + profit margin should be at least 40%.\n- Balances growth against profitability for software.");
C(T,2,"In the Rule of 40, when do you use EBITDA margin versus FCF margin?","EBITDA for growing, private or mid-market companies; FCF for mature ones.\n- FCF shows actual cash generation once growth investment settles.");
C(T,2,"What is the SaaS magic number?","Net new ARR this quarter / last quarter's S&M spend.\n- Below 0.5x is inefficient; around 1x or more is strong.");
C(T,2,"What are NRR and GRR?","Revenue retained from existing customers.\n- GRR: after churn and downgrades only, max 100%.\n- NRR: also counts upsells, can exceed 100%.");
C(T,3,"Expected NRR and GRR: accounting software versus GTM automation software?","Accounting: high GRR, modest NRR. GTM tools: higher NRR, lower GRR.\n- Accounting is sticky and seat-based with few upsells.\n- GTM is usage-based with expansion, but smaller, more churn-prone customers.");
C(T,2,"What is CAC payback?","Months to earn back the cost of acquiring a customer.\n- CAC / (monthly revenue per customer x gross margin).\n- Under 12 to 18 months is good.");
C(T,2,"What is LTV/CAC?","Lifetime gross profit of a customer / cost to acquire them.\n- Above 3x is the usual benchmark.");
C(T,2,"What is the burn multiple?","Net burn / net new ARR.\n- Below 1x is efficient; above 2x is a warning.");
C(T,1,"Why do rising interest rates hit growth stocks harder?","Their value sits further in the future.\n- Higher discount rates shrink distant cash flows the most.");
C(T,2,"What does an inverted yield curve signal?","Markets expect lower rates ahead, often because of a slowdown.\n- Short rates above long rates has preceded many recessions.");
C(T,2,"How do rates link to equity multiples?","Higher rates usually mean lower multiples.\n- Higher risk-free rate raises the discount rate.\n- Bonds become more competitive with stocks.");
C(T,1,"What is the Fed's dual mandate?","Maximum employment and stable prices.\n- It targets about 2% inflation.");
C(T,2,"What does a strong dollar do to US multinationals?","Lowers their reported foreign earnings.\n- Overseas revenue converts into fewer dollars.");
C(T,2,"What is the equity risk premium?","Extra return investors demand for stocks over risk-free bonds.\n- Usually assumed around 5 to 6%.");
C(T,2,"What is a credit spread and what does widening tell you?","Yield over Treasuries for credit risk.\n- Widening spreads mean rising perceived default risk or risk aversion.");
C(T,2,"Why does billings growth matter for SaaS?","It leads revenue.\n- Billings = revenue + change in deferred revenue.");
C(T,3,"Why might two SaaS companies with the same revenue trade very differently?","Growth, retention and margins.\n- NRR, gross margin, efficiency of growth, and the quality of revenue (recurring versus services).");

})();

// ---- wacc.js
;(function(){
var T="WACC";
C(T,1,"What is WACC and why use it in a DCF?","The blended required return of all capital providers.\n- WACC = E/V x Ke + D/V x Kd x (1 - t).\n- It discounts UFCF because UFCF belongs to debt and equity holders.");
C(T,1,"Why multiply the cost of debt by (1 - tax rate)?","Interest is tax deductible.\n- The tax shield lowers the real cost of borrowing.");
C(T,1,"How do you calculate cost of equity?","CAPM: risk-free rate + beta x equity risk premium.\n- Risk-free: 10-year Treasury yield.\n- Beta: from comps.\n- ERP: about 5 to 6%. Add a size premium for small companies.");
C(T,2,"Risk-free 5%, beta 1.5, ERP 6%. What is cost of equity?","14%.\n- 5% + 1.5 x 6%.");
C(T,2,"How do you find the cost of debt?","The rate the company would pay to borrow today.\n- Yield to maturity on its traded bonds.\n- Or the spread for its credit rating over Treasuries.\n- Not the old coupon.");
C(T,2,"60% equity at 12%, 40% debt at 6% pretax, tax 25%. What is WACC?","9.0%.\n- 0.6 x 12% = 7.2%.\n- 0.4 x 6% x 0.75 = 1.8%.");
C(T,2,"How does WACC change as a company adds debt?","Falls at first, then rises.\n- Debt is cheaper and tax deductible.\n- But more debt raises both Ke and Kd, and distress costs eventually win. U-shaped.");
C(T,3,"Does a higher beta always mean a higher WACC?","No.\n- If beta is high because of leverage, the cheap debt weight is also higher.\n- Unlevered beta is the clean measure of business risk.");
C(T,3,"Can cost of debt be higher than cost of equity?","Not in theory, since debt is senior and less risky.\n- It can appear for distressed companies or when inputs are stale.");
C(T,2,"What is beta?","Sensitivity of a stock's returns to the market.\n- Beta 1 moves with the market; above 1 more volatile; below 1 less.\n- Measures systematic risk only.");
C(T,2,"Can beta be negative or zero? Examples?","Yes to both.\n- Negative: assets that rise when markets fall, like gold at times or a put option.\n- Zero: T-bills, a lottery ticket, a coin toss.");
C(T,3,"Why do we unlever and relever beta?","Comps have different leverage.\n- Unlever to strip out each comp's capital structure.\n- Average the asset betas, then relever at the target's capital structure.");
C(T,3,"What are the formulas for unlevering and relevering beta?","Unlevered = levered / (1 + (1 - t) x D/E).\n- Relevered = unlevered x (1 + (1 - t) x target D/E).");
C(T,3,"Comps have unlevered betas of 1.2, 1.4, 1.8 and 1.6. Target has $800M market cap and $400M debt. What is the levered beta?","Average unlevered beta is 1.5; you need the tax rate to relever.\n- D/E = 0.5.\n- At 25% tax: 1.5 x (1 + 0.75 x 0.5) = 2.06.");
C(T,2,"Higher beta: a software startup or a mature automaker? A tech company or a furniture maker?","Startup and tech.\n- More volatile earnings and more sensitivity to the economy and to risk appetite.");
C(T,3,"Would a commercial-stage biotech have a higher or lower beta than a pre-commercial one?","Usually lower.\n- Revenue and product diversity reduce risk.\n- Pre-commercial value hinges on binary trial outcomes.");
C(T,3,"How does preferred stock enter WACC?","Add a preferred weight x cost of preferred.\n- Cost is roughly the dividend yield.\n- No tax adjustment: preferred dividends are not deductible.");
C(T,3,"Where does cost of preferred sit versus debt and equity?","Between them.\n- Junior to debt and no tax shield, so above debt.\n- Senior to common with a fixed dividend, so below equity.");
C(T,2,"Higher WACC: WeWork or Apple?","WeWork.\n- Riskier business, higher beta, wider credit spreads.");
C(T,3,"How does WACC respond to a higher tax rate?","It falls.\n- Bigger tax shield makes after-tax debt cheaper.\n- But UFCF also falls, so value still usually drops.");
C(T,3,"How can you lower WACC without changing the tax rate?","Move toward the optimal capital structure.\n- Add some cheaper debt.\n- Lower business risk, or benefit from lower rates and tighter spreads.");
C(T,3,"Describe the Modigliani-Miller view of capital structure.","Without taxes, capital structure does not change firm value.\n- WACC is flat: cheaper debt is offset by a higher cost of equity.\n- With taxes, debt adds value through the tax shield until distress costs offset it.");
C(T,3,"If a company pays down debt, what happens to cost of equity and WACC?","Cost of equity falls; WACC may rise.\n- Less financial risk lowers levered beta.\n- But there is less cheap, tax-deductible debt in the mix.");
C(T,3,"How do you calculate WACC for a company with several divisions?","Ideally a separate WACC for each division.\n- Use each division's comps for beta and capital structure.\n- Value each, then sum the parts.");
C(T,3,"How do you calculate cost of equity for cash flows in a foreign currency?","Build CAPM in that currency.\n- Use that country's risk-free rate, add a country risk premium if needed.\n- Discount local-currency cash flows at a local-currency rate.");
C(T,2,"Why use market weights rather than book weights in WACC?","Investors require returns on what their capital is worth today.\n- Book equity is a historical number and can be far from market value.");
C(T,2,"Should WACC use the current or a target capital structure?","Target.\n- The DCF covers many years, so use the long-run mix the company is moving toward.");
C(T,2,"Why use comps' betas rather than the company's own regression beta?","Own betas are noisy.\n- Short history, illiquid trading or recent changes distort them.\n- A peer average gives a steadier estimate of business risk.");
C(T,3,"What is a Bloomberg adjusted beta?","Raw beta pulled toward 1.\n- Adjusted = 2/3 x raw + 1/3 x 1.\n- Betas tend to drift toward the market average over time.");
C(T,3,"A company has no taxable income. What does that do to its WACC?","No tax shield, so use the pretax cost of debt.\n- WACC is higher than the formula with (1 - t) would suggest.");
C(T,3,"How do you get WACC for a private company?","Borrow from public comps.\n- Peer unlevered betas, relevered at a target capital structure.\n- Often add size and illiquidity premiums.");
C(T,3,"Why would a manufacturer support more leverage than a software company?","Tangible assets and steady cash flows.\n- Collateral lowers lender risk.\n- Though recurring-revenue software now borrows heavily too.");
C(T,2,"What does WACC mean conceptually?","The return the business must earn to satisfy everyone who funded it.\n- Also the opportunity cost of capital for a project of that risk.");

})();
